/* 論語選—子路曾皙冉有公西華侍坐 */
(window.TB_LESSONS = window.TB_LESSONS || []).push(["論語選—子路曾皙冉有公西華侍坐", {"title": "論語選—子路曾皙冉有公西華侍坐", "textPages": [{"seg": "第一段", "title": "第一段", "book": "課本 P.100", "noteStart": 1, "sub": "孔子問志——師生相處氣象", "pian": "孔子問志——師生相處氣象，凸顯孔子和藹可親、循循善誘的長者風範。", "xi": "以「言志」貫串全文。「侍坐」二字摹寫現場，用詞簡約，與孔子平易親切的問話相配合，當時情景可見一斑。", "fan": "子路、曾皙、冉有、公西華陪孔子坐著。孔子說：「不要因為我的年紀比你們稍大，就不好意思說出自己的志向。平日你們總是說：『沒有人了解我！』如果有人了解你們，那你們用什麼來表現自己的才能？」", "lines": [{"text": "{n:1|子路}、{n:2|曾皙}、{n:3|冉有}、{n:4|公西華}侍坐。", "tr": "子路、曾皙、冉有、公西華陪孔子坐著。", "cite": "侍坐", "mean": "弟子們依長幼次序侍坐於孔子身旁，表現出師生間日常的輕鬆和諧。"}, {"text":"子曰：「{n:5|以吾一日長乎爾}，{n:6|毋吾以也}。","tr":"孔子說：「不要因為我的年紀比你們稍大，就不好意思說出自己的志向。","mean":"孔子刻意以『年長』自謙、以『平日抱怨無人知』為引，其真正用意是解除弟子尊卑長幼的顧慮，營造敢於言志的氣氛。","cite":"以吾一日長乎爾","rhet":[["倒裝","<span class=\"tp-rq\">一日長乎爾</span>──即「長乎爾一日」。"],["省略","<span class=\"tp-rq\">毋吾以也</span>──即「毋以吾長於爾而不敢言」。"],["倒裝","<span class=\"tp-rq\">毋吾以也</span>──即「毋以吾也」。"]],"meanShort":"孔子以和藹的措辭與態度，解除弟子尊卑長幼的顧慮，開啟各自言志的良好氣氛","rhetShort":["以吾長乎爾一日",null,"毋以吾也"]}, {"text":"{n:7|居}則曰：『不吾知也！』如{g:或|有人}知爾，{n:8|則何以哉}？」","tr":"平日你們總是說：『沒有人了解我！』如果有人了解你們，那你們用什麼來表現自己的才能？」","rcite":["不吾知也"],"rhet":[["倒裝","<span class=\"tp-rq\">不吾知也</span>──否定句代詞賓語前置，即『不知吾也』；『毋吾以也』（＝毋以吾也）、『則何以哉』（＝則以何哉）亦同。"],["倒裝","<span class=\"tp-rq\">則何以哉</span>──即『則以何哉』。"]],"rhetShort":["不知吾也","則以何哉"]}], "qa": [["孔子說：「以吾一日長乎爾，毋吾以也！」這句話的意思是要學生：<br>□1.不要因為老師在場就不敢講出真心話來<br>□2.不要因為老師年長就不好意思說出志向<br>□3.不要因為老師年長就不好意思提出批判", "2.不要因為老師年長就不好意思說出志向"], ["孔子詢問各人志向，為何一開始說『以吾一日長乎爾，毋吾以也』？", "去除學生的戒慎恐懼，緩和現場氣氛，如此學生才會說出內心真正的想法。"]], "notes": [["子路", "姓仲名由，字子路，一字季路，魯國人，率直好勇，擅長政事，小孔子九歲。"], ["曾皙", "姓曾名點，字皙（ㄒㄧ），魯國人，放浪灑脫，小孔子二十餘歲，與兒子曾參同為孔子弟子。"], ["冉有", "姓冉名求，字子有，魯國人，謙和多才藝，擅長政事，小孔子二十九歲。"], ["公西華", "姓公西名赤，字子華，魯國人，熟習禮儀，擅長外交，小孔子四十二歲。"], ["以吾一日長乎爾", "因為我的年紀比你們稍長。以，因為。一日長乎爾，即『長乎爾一日』的倒裝。長，ㄓㄤˇ。"], ["毋吾以也", "即『毋以吾也』。不要因為我年長而不好意思說話。"], ["居", "平日。"], ["則何以哉", "即『則以何哉』。那麼你們用什麼來表現自己的才能？以，用。"]]}, {"seg": "第二段", "title": "第二段", "book": "課本 P.101", "noteStart": 9, "sub": "弟子述志——子路", "pian": "弟子述志——子路，率爾而對（軍事、禮義）。", "xi": "子路率爾回答，個性衝動、自負；孔子『哂之』褒貶寓含其中，不助長其驕矜之氣，顯示為師者因材施教的細膩。", "fan": "子路不加思索地搶先答道：「一個擁有一千輛兵車的國家，夾處在大國之間，又受到外敵侵略，接著又鬧饑荒，讓我來治理，等到三年，可使人民有勇氣，並且懂得禮義。」孔子微微一笑。", "lines": [{"text": "子路{n:9|率爾}而對曰：「{n:10|千乘之國}，{n:11|攝}乎大國之間，{n:12|加之以師旅}，{n:13|因之以饑饉}。", "tr": "子路不加思索地搶先答道：「一個擁有一千輛兵車的國家，夾處在大國之間，又受到外敵侵略，接著又鬧饑荒，", "rcite": ["師旅"], "rhet": [["借代", "<span class=\"tp-rq\">師旅</span>──以『師旅（軍隊）』借代『戰爭』。"]], "cite": "率爾而對", "mean": "顯露其粗豪、好勇的性格。","rhetShort":["戰爭"]}, {"text":"{n:14|由}也{z:為|ㄨㄟˊ，治理}之，{n:15|比及}三年，可使有勇，且知{n:16|方}也。」","tr":"讓我來治理，等到三年，可使人民有勇氣，並且懂得禮義。」","cite":"比及三年，可使有勇，且知方也","mean":"子路自言必能使人民有勇且知義，反映出子路的自信與直率。<span class='tm-sup'>孔子曾曰：「由也，千乘之國，可使治其賦（軍事）也。」</span>"}, {"text": "夫子{n:17|哂}之。", "tr": "孔子微微一笑。", "mean": "子路以極不利的處境（大國夾處、外患、饑荒）反襯自己三年治國之效，凸顯其自信直率；而『哂之』顯示孔子對其『不讓』有所保留。<br>孔子深知子路喜歡追求英雄式的成功，卻又誇言禮義（方），故未讚許子路，只神祕微笑以免助長其驕矜之氣，顯示出為師者因材施教的細膩。", "cite": "夫子哂之","meanShort":"孔子深知子路喜歡追求英雄式的成功，卻又誇言禮義（方），故未讚許子路，只神祕微笑以免助長其驕矜之氣，顯示出為師者因材施教的細膩"}], "qa": [["『子路率爾而對曰』可看出子路的性格是？", "率直、衝動（粗豪好勇）。"], ["子路的回應內容何處表現對自己能力的自信？", "以『千乘之國、夾處大國、外敵侵略、饑饉』的極不利條件，對比『三年、有勇、知方』的高成就，足見其自信。"]], "notes": [["率爾", "輕率的樣子，此有搶先之意。"], ["千乘之國", "擁有一千輛兵車的國家。乘（ㄕㄥˋ），古代計算車輛的單位，此指兵車。春秋時代常以兵車數量表示國家的大小與實力。"], ["攝", "ㄕㄜˋ，夾處。"], ["加之以師旅", "又受到外敵的侵略。加，加上。師旅，軍隊。"], ["因之以饑饉", "接著又鬧饑荒。因，接連。饑（ㄐㄧ）饉（ㄐㄧㄣˇ），荒年。"], ["由", "子路自稱。古代禮俗，自稱或稱呼晚輩時以名，尊稱他人時則以字。"], ["比及", "等到。『比』和『及』同義。比，ㄅㄧˋ。"], ["方", "此指禮義。"], ["哂", "ㄕㄣˇ，微笑。"]]}, {"seg": "第三段", "title": "第三段", "book": "課本 P.101–102", "noteStart": 18, "sub": "弟子述志——冉有", "pian": "弟子述志——冉有，問而後答（經濟、民生）。", "xi": "與子路自詡能做到禮義教化相較，冉有卻表示須待更賢能的君子才能實行禮樂，呈現冉有『退』與『讓』的個性。", "fan": "「求，你怎樣呢？」冉有回答：「一個六、七十里或五、六十里見方的小國，讓我治理，三年後可使人民富足。至於禮樂教化，就只有等待更有才德的君子了。」", "lines": [{"text": "「求，爾何如？」", "tr": "「求，你怎樣呢？」"}, {"text":"對曰：「{n:18|方六、七十}，{n:19|如}五、六十，求也為之，比及三年，可{n:20|使足民}。","tr":"冉有回答：「一個六、七十里或五、六十里見方的小國，讓我治理，三年後可使人民富足。","rcite":["可使足民"],"rhet":[["倒裝","<span class=\"tp-rq\">可使足民</span>──即『可使民足』的倒裝。"]],"cite":"方六、七十，如五、六十","mean":"越說越小，反映冉有的謙退保守。","cite2":"比及三年，可使足民","mean2":"<span class='tm-sup'>孔子曾曰：「求也，千室之邑，百乘之家，可使為之宰也。」</span>","rhetShort":["可使民足"]}, {"text":"{n:21|如}其禮樂，以{n:22|俟}君子。」","tr":"至於禮樂教化，就只有等待更有才德的君子了。」","mean":"冉有先言小國、再言僅能『足民』、又把禮樂讓與君子，句句退讓，與子路的『率爾』形成對比，見其謙遜保守。","cite":"如其禮樂，以俟君子","meanShort":"冉有句句退讓，可見其謙遜保守，與子路形成對比。"}], "qa": [["冉有說『如其禮樂，以俟君子』的意思是？", "自認不具禮樂教化之長才（謙退）。"]], "notes": [["方六、七十", "每邊長六、七十里的土地面積，此指小國。方，計算面積的用語。"], ["如", "或者。下文『如會同』的『如』義同。"], ["使足民", "讓人民富足。（『足民』即『民足』的倒裝）"], ["如", "至於。"], ["俟", "ㄙˋ，等待。"]]}, {"seg": "第四段", "title": "第四段", "book": "課本 P.102", "noteStart": 23, "sub": "弟子述志——公西華", "pian": "弟子述志——公西華，問而後答（外交）。", "xi": "孔子一一垂問弟子，聆聽而不評論，為之後與曾皙的對話埋下伏筆；未在一開始即催促最小的公西華發言，也顯示孔子因材施教的細膩安排。", "fan": "「赤，你怎樣呢？」公西華回答：「不敢說能做好，只希望能有學習的機會。在諸侯祭祀或朝覲、會盟的典禮上，我願意穿著禮服、戴著禮帽，做個贊禮的小相。」", "lines": [{"text": "「赤，爾何如？」", "tr": "「赤，你怎樣呢？」"}, {"text": "對曰：「非曰能之，願學焉。", "tr": "公西華回答：「不敢說能做好，只希望能有學習的機會。", "mean": "公西華以『非曰能之，願學焉』一字之退，較冉有更為謙抑；所志雖為宗廟會同的外交大事，卻自居『小相』。<br>公西華年紀最小，「能」與「學」一字之改，更見謙遜。", "cite": "非曰能之，願學焉","meanShort":"公西華年紀最小，『能』與『學』一字之改，更見謙遜"}, {"text":"{n:23|宗廟之事}，如{n:24|會同}，{n:25|端章甫}，願{z:為|ㄨㄟˊ}{n:26|小相}焉。」","tr":"在諸侯祭祀或朝覲、會盟的典禮上，我願意穿著禮服、戴著禮帽，做個贊禮的小相。」","cite":"宗廟之事，如會同，端章甫，願為小相焉","mean":"<span class='tm-sup'>孔子曾曰：「赤也，束帶立於朝，可使與賓客言也。」</span>"}], "qa": [["公西華熱衷宗廟祭祀與諸侯朝覲、會盟，最適合的工作部門是？", "外交部。"], ["從冉有、公西華的回答中，哪些地方看出他們謙退？", "冉有僅能使小國人民富足、禮樂待君子；公西華不敢言『能』，僅願學、做小相。"]], "notes": [["宗廟之事", "此指諸侯祭祀祖先的大典。"], ["會同", "指諸侯朝覲天子或諸侯會盟之事。"], ["端章甫", "穿著禮服，戴著禮帽。端，玄端，古代禮服。章甫（ㄈㄨˇ），玄冠，古代禮帽。此皆作動詞。"], ["小相", "ㄒㄧㄤˋ，典禮中擔任司儀或贊禮（輔佐禮儀進行）的人。小，謙詞。"]]}, {"seg": "第五段", "title": "第五段", "book": "課本 P.102–103", "noteStart": 27, "sub": "弟子述志——曾皙（禮樂融合）", "pian": "弟子述志——曾皙，孔子問、止瑟而答（禮樂融合）。", "xi": "曾皙所描繪的是禮樂治理下太平社會的縮影，與孔子『風清俗美、人民安樂』的政治理想相符，故深獲嘉許（此說以朱熹為代表）。『鼓瑟希』使讀者恍然大悟，原來對話從一開始便在音樂聲中進行。", "fan": "「點，你怎樣呢？」曾皙正鼓瑟，瑟聲漸歇，鏗然一聲，放下瑟站起來，答：「我和他們三位所講的不同。」孔子：「有什麼關係呢？不過各自談談志向罷了。」曾皙：「晚春時節，穿上做好的春裝，與五、六個成年人、六、七個孩童，到沂水邊洗洗澡，在求雨的祭壇上吹風乘涼，然後唱著歌回家。」孔子嘆息：「我贊同點所說的呀！」", "lines": [{"text": "「點，爾何如？」", "tr": "「點，你怎樣呢？」"}, {"text":"{n:27|鼓瑟希}，{n:28|鏗爾}，{n:29|舍瑟而作}，對曰：「異乎三子者之{n:30|撰}。」","tr":"曾皙正鼓瑟，瑟聲漸歇，鏗然一聲，放下瑟站起來，答：「我和他們三位所講的不同。」","cite":"鼓瑟希","mean":"此時才問年紀第二大的曾皙，「鼓瑟希」使讀者恍然大悟，原來這場對話從一開始便是在音樂聲中進行的。","cite2":"舍瑟而作","mean2":"曾皙以閒雅的態度結束彈瑟，「作」這個起身的動作，將曾皙的恭敬之態刻劃得極傳神。","rhet":[["轉品","<span class=\"tp-rq\"><b class='rq-hi'>鼓</b>瑟希</span>──『鼓』本為名詞，此作動詞（名→動）。"]],"rhetShort":["名→動"]}, {"text":"子曰：「何{n:31|傷}乎？亦各言其志也。」","tr":"孔子：「有什麼關係呢？不過各自談談志向罷了。」","rcite":["何傷乎"],"rhet":[["激問","<span class=\"tp-rq\">何傷乎</span>──明知故問以寬解曾皙，答案即在問中。"]],"rhetShort":["明知故問以寬解曾皙"]}, {"text": "曰：「{n:32|莫春}者，春服既成，{n:33|冠者}五、六人，童子六、七人，{n:34|浴乎沂}，{n:35|風乎舞雩}，詠而歸。」", "tr": "曾皙：「晚春時節，穿上做好的春裝，與五、六個成年人、六、七個孩童，到沂水邊洗洗澡，在求雨的祭壇上吹風乘涼，然後唱著歌回家。」", "rcite": ["風乎舞雩"], "rhet": [["轉品", "<span class=\"tp-rq\">風乎舞雩</span>──『風』本為名詞，此作動詞『吹風乘涼』（名→動）。"]], "cite": "莫春者，春服既成，冠者五、六人，童子六、七人，浴乎沂，風乎舞雩，詠而歸", "mean": "曾皙胸次悠然，從容體道，所描述自在和樂的生活景象，展現與萬物交感的襟懷。","rhetShort":["名→動"]}, {"text":"夫子{n:36|喟然}嘆曰：「吾{n:37|與}點也！」","tr":"孔子嘆息：「我贊同點所說的呀！」","mean":"曾皙不談治國之術，而以暮春出遊、浴沂風雩的和樂景象言志，展現禮樂教化下人與自然交融的太平氣象；孔子『喟然』而『與』，正因此境與其淑世理想相契。<br>「吾與點也」與孔子<span class='tm-sup'>「邦有道，則仕；邦無道，則可卷而懷之」（《論語．衛靈公》）</span>的思想相映。但「卷而懷之」非孔子初衷，故喟然長嘆。","cite":"吾與點也","meanShort":"「吾與點也」與孔子<span class='tm-sup'>「邦有道，則仕；邦無道，則可卷而懷之」（《論語．衛靈公》）</span>的思想相映。但「卷而懷之」非孔子初衷，故喟然長嘆"}], "qa": [["孔子與弟子言志時，曾皙在一旁鼓瑟，你有何看法？", "（開放）一說為灑脫不羈、從容自在；一說依禮當停止動作恭敬回答，鼓瑟則近疏狂。請自由發揮。"], ["下列何者最可能是孔子『喟然稱許』曾皙的理由？", "孔子認同曾皙所嚮往的生活境界（禮樂治理下的太平氣象）。"]], "notes": [["鼓瑟希", "彈瑟聲音漸弱。鼓，彈奏。希，通『稀』。"], ["鏗爾", "ㄎㄥ，鏗的一聲，結束彈奏。鏗，狀聲詞。"], ["舍瑟而作", "放下瑟，站起來。舍（ㄕㄜˇ），通『捨』。作，起立。"], ["撰", "此指陳述。"], ["傷", "妨礙。"], ["莫春", "晚春，農曆三月。莫（ㄇㄨˋ），『暮』的本字。"], ["冠者", "ㄍㄨㄢˋ，成年男子。古代男子二十歲時舉行加冠禮，表示成年。"], ["浴乎沂", "到沂（ㄧˊ）水邊洗浴。沂，河水名，在魯國都城曲阜南，源出山東省鄒城市。"], ["風乎舞雩", "在求雨的祭壇上乘涼。風（此作動詞）。舞雩（ㄩˊ），古時求雨的祭壇；雩，求雨的祭典名稱。"], ["喟然", "ㄎㄨㄟˋ，嘆息的樣子。"], ["與", "贊同、讚許。"]]}, {"seg": "第六段", "title": "第六段", "book": "課本 P.103–104", "noteStart": 38, "sub": "孔子評志——強調禮讓", "pian": "孔子評志——強調禮讓。", "xi": "孔子的回答均針對『其言不讓』說明『是故哂之』。全文以孔子具啟發性的問話開頭，又以其評語作結，『言志』二字貫穿全文，透過此線索表現『治國以禮』的思想，脈絡十分清楚。", "fan": "子路、冉有、公西華都出去了，曾皙留在後頭，問：「他們三位的話怎麼樣？」孔子：「也就是各自談談志向罷了。」曾皙：「老師為什麼笑由呢？」孔子：「治國應當講禮，子路的話毫不謙讓，所以我笑他。」曾皙：「求所說的，不是治國的事嗎？（不然老師怎麼都沒有表示？）」孔子：「怎麼見得六、七十里或五、六十里見方的地方，不算一個國家呢？（因為冉求很謙虛，所以我沒表示什麼，但他所說的，當然是屬於治理國家的事。）」曾皙：「赤所說的，不是治國的事嗎？（不然老師怎麼也沒有表示？）」孔子：「宗廟會同，不是諸侯的事又是什麼？公西華只能做小相，又有誰能做大相呢？」", "lines": [{"text": "三子者出，曾皙後。", "tr": "子路、冉有、公西華都出去了，曾皙留在後頭，", "cite": "三子者出，曾皙後", "mean": "曾皙很想知道孔子對另外三位的評價，故刻意留在後邊。自此對話者從五人變成二人，高明的描寫技巧，使本章讀來更像一篇有趣的極短篇小說。"}, {"text": "曾皙曰：「{n:38|夫}三子者之言何如？」", "tr": "問：「他們三位的話怎麼樣？」"}, {"text": "子曰：「亦各言其志也已矣。」", "tr": "孔子：「也就是各自談談志向罷了。」", "cite": "各言其志也已矣", "mean": "此與前文「亦各言其志也」相呼應。「言志」二字是全文章法的主軸，故再度強調。"}, {"text": "曰：「夫子何哂由也？」", "tr": "曾皙：「老師為什麼笑由呢？」"}, {"text":"曰：「{z:為|ㄨㄟˊ}國以禮，其言不{n:39|讓}，是故哂之。」","tr":"孔子：「治國應當講禮，子路的話毫不謙讓，所以我笑他。」","mean":"孔子藉與曾皙的問答點明評志標準在『禮讓』：哂子路非否定其才，而在其『不讓』；冉有、公西華雖同為治國之志，因言辭謙退故不哂。全章歸結於『為國以禮』。","cite":"為國以禮，其言不讓","meanShort":"點明評志標準在『禮讓』，全章歸結於『為國以禮』。"}, {"text": "「{n:40|唯求則非邦也與}？」", "tr": "曾皙：「求所說的，不是治國的事嗎？（不然老師怎麼都沒有表示？）」"}, {"text": "「{n:41|安}見方六、七十，如五、六十，而非邦也者？」", "tr": "孔子：「怎麼見得六、七十里或五、六十里見方的地方，不算一個國家呢？（因為冉求很謙虛，所以我沒表示什麼，但他所說的，當然是屬於治理國家的事。）」"}, {"text": "「唯赤則非邦也與？」", "tr": "曾皙：「赤所說的，不是治國的事嗎？（不然老師怎麼也沒有表示？）」"}, {"text":"「宗廟會同，{n:42|非諸侯而何}？{n:43|赤也為之小，孰能為之大}？」","tr":"孔子：「宗廟會同，不是諸侯的事又是什麼？公西華只能做小相，又有誰能做大相呢？」","rcite":["非諸侯而何"],"rhet":[["激問","<span class=\"tp-rq\">非諸侯而何</span>、<span class=\"tp-rq\">孰能為之大</span>──連用激問，肯定公西華的才能與謙遜。"]],"cite":"宗廟會同，非諸侯而何","mean":"「宗廟會同」與「諸侯（之事）」皆同為政治激問。","cite2":"赤也為之小，孰能為之大","mean2":"孔子肯定公西華的才能與謙遜。","rhetShort":["肯定公西華的才能與謙遜。"]}], "qa": [["孔子為何『哂由』（笑子路）？", "因子路『其言不讓』——治國當以禮，子路言志卻毫不謙讓。"], ["本文描寫孔子課堂實況，在寫作技巧上有何特殊點？", "《論語》大多為單一人物之口述語錄，本文特殊處在於全文以對話的形式呈現：先以「侍坐」點出師生共同討論的場景；行文至一半才出現「鼓瑟希」，則使讀者赫然發現原來對話從一開始便是在音樂聲中進行的；最後則以「三子者出，曾皙後」交代對話者從五人變成二人。其類似小說的描寫技巧，使本文的情節充滿張力。"], ["本文呈現孔子哪些教育方法？", "本文表現出孔子有教無類、循循善誘、因材施教的教育方式，並透過問答方式，讓學生進一步思考人生目標與價值。"], ["下列選項哪些是本文含括的題材內容？（多選）<br>□1.孔子要弟子談個人的志向<br>□2.子路表達帶軍布陣的志向<br>□3.冉有表達經濟富民的志向<br>□4.公西華要擔任贊禮司儀官<br>□5.曾皙表達隨遇而安的理想<br>□6.孔子要求學生要適性發展", "1、3、4"], ["下列選項哪些是本文所使用的寫作技巧？（多選）<br>□1.以對話方式行文敘事<br>□2.以「侍坐」點出場景<br>□3.採先分述再總評的布局", "1、2、3"]], "notes": [["夫", "ㄈㄨˊ，彼、那。"], ["讓", "謙讓。"], ["唯求則非邦也與", "難道冉求所說的就不是治國的事嗎？唯，語首助詞。與（ㄩˊ），通『歟』。"], ["安", "何、怎麼。"], ["非諸侯而何", "如果不是和諸侯相關的國家大事又是什麼事呢？"], ["赤也為之小，孰能為之大", "公西華謙稱只能做小相，又有誰能做大相呢？"]]}], "extras": {"authorPages": [{"label": "作者·課本", "head": "孔子（課本作者介紹）", "body": "<div class=\"au-fig\"><img class=\"au-img\" src=\"img/侍坐/e4d18d34956eee03.jpg\" alt=\"孔子畫像（課本 P.99）\"><div class=\"au-cap\">◀ 孔子畫像（課本 P.99）</div></div>孔子名丘，字仲尼，春秋魯國陬邑（今山東省曲阜市）人。生於魯襄公二十二年（西元前五五一年），卒於魯哀公十六年（西元前四七九年），年七十三。孔子三歲喪父，由母親扶養成人。為了謀生，他做過許多卑微的工作。三十歲開始講學，五十二歲擔任魯國大司寇（主掌司法、刑獄及社會治安），在外交和內政上均有建樹。後因魯君荒於政事，孔子失望之餘，帶領弟子周遊列國，尋求仕進，可惜未能獲得任用。六十八歲回到魯國，投身教育，並整理《詩》、《書》、《禮》、《樂》、《易》、《春秋》。孔子思想以「仁」為中心，「忠、恕」為行仁的方法，重視禮樂教化。他首開平民教育之風，有教無類，因材施教，後世尊稱為「至聖先師」、「萬世師表」。", "supList": [["因材施教", "針對學生不同的個性、資質給予不同的教導。本文孔子對子路『哂之』、對曾皙『與之』，即因材施教的展現。"], ["忠、恕", "盡己之謂『忠』，推己及人之謂『恕』。曾子：『夫子之道，忠恕而已矣。』"], ["有教無類", "不分貴賤、貧富、地域，只要備『束脩』之禮即可受教。"]]}, {"label": "作者·補充｜周遊列國", "head": "孔子周遊列國（作者補充）", "body": "孔子五十五歲起周遊列國十四年，歷衛、曹、宋、齊、鄭、晉、陳、蔡、楚等地，尋求施展政治理想的機會，未能獲重用，六十八歲返魯。<br><br><div class=\"zy-wrap\" data-step=\"0\" data-max=\"2\"><div class=\"zy-hint\">孔子周遊列國。點「下一段 ▶」讓長圖向左移動，逐段講解，可「回到開始」。</div><div class=\"zy-viewport\"><div class=\"zy-track\"><img class=\"zy-img\" src=\"img/侍坐/26f3bb710a3fbf97.jpg\" alt=\"孔子周遊列國長橫圖（翰林教材PPT）\"><span class=\"zy-lbl on\" data-stop=\"0\" style=\"left:18.4%;top:53.1%\">由魯到衛</span><span class=\"zy-lbl on\" data-stop=\"0\" style=\"left:29.1%;top:52.3%\">離衛去陳再返衛</span><span class=\"zy-lbl on\" data-stop=\"0\" style=\"left:41.0%;top:52.3%\">離衛返魯</span><span class=\"zy-lbl\" data-stop=\"1\" style=\"left:49.8%;top:42.8%\">再返衛國</span><span class=\"zy-lbl\" data-stop=\"1\" style=\"left:61.8%;top:36.1%\">離衛，經曹到宋，再到鄭國</span><span class=\"zy-lbl\" data-stop=\"2\" style=\"left:72.9%;top:36.1%\">陳蔡遊歷</span><span class=\"zy-lbl\" data-stop=\"2\" style=\"left:81.5%;top:36.1%\">前往楚國</span><span class=\"zy-lbl\" data-stop=\"2\" style=\"left:90.5%;top:36.1%\">結束周遊列國</span></div></div><div class=\"zy-cap\"><div class=\"zy-cap-item on\" data-stop=\"0\"><b class=\"zy-cap-h\">由魯到衛</b>魯國辦郊祭，孔子未收到祭肉，知抱負無法實現，離魯去衛，周遊列國自此開始。</div><div class=\"zy-cap-item on\" data-stop=\"0\"><b class=\"zy-cap-h\">離衛去陳再返衛</b>離衛去陳途中，因相貌近似殘害匡地的宰相陽貨，而被匡人圍攻，受困於匡邑，解圍後再度返衛。</div><div class=\"zy-cap-item on\" data-stop=\"0\"><b class=\"zy-cap-h\">離衛返魯</b>因不齒衛靈公耽溺美色，再度離開衛國，回到魯國。</div><div class=\"zy-cap-item\" data-stop=\"1\"><b class=\"zy-cap-h\">再返衛國</b>返魯不久，再到衛國，衛靈公雖以禮相待，但未能重用。晉內亂，衛靈公請教孔子作戰之法，孔子僅說自己只聽過祭祀禮儀之事，便離開衛國。</div><div class=\"zy-cap-item\" data-stop=\"1\"><b class=\"zy-cap-h\">離衛，經曹到宋，再到鄭國</b>離開衛國後，孔子經曹到宋，再到鄭國。期間因批評宋國司馬而險被殺害，逃亡途中與弟子走散，落魄模樣被鄭人稱為「喪家犬」。</div><div class=\"zy-cap-item\" data-stop=\"2\"><b class=\"zy-cap-h\">陳蔡遊歷</b>由鄭國到陳國後，孔子於陳、蔡間遊歷。</div><div class=\"zy-cap-item\" data-stop=\"2\"><b class=\"zy-cap-h\">前往楚國</b>應楚昭王之聘，取道陳、蔡前往楚國，卻受困於此，絕糧七日。後楚昭王派軍隊來迎接，始得解除危機。楚昭王過世後，孔子返衛國。</div><div class=\"zy-cap-item\" data-stop=\"2\"><b class=\"zy-cap-h\">結束周遊列國</b>自衛返魯，結束周遊列國，從此致力於教育職志。並整理《詩》、《書》，作《春秋》。</div></div><div class=\"zy-ctrl\"><button class=\"zy-btn zy-prev\" onclick=\"zyStep(this,-1)\" disabled>◀ 上一段</button><button class=\"zy-btn\" onclick=\"zyReset(this)\">⟳ 回到開始</button><button class=\"zy-btn zy-next\" onclick=\"zyStep(this,1)\">下一段 ▶</button><span class=\"zy-ind\">第 1 / 3 段</span></div></div>"}, {"label": "作者·補充｜四科十哲", "head": "孔門四科十哲（作者補充）", "body": "孔子一生講學授徒無數，著名弟子有『孔門四科十哲』：<br><br><table class=\"ly-table\"><thead><tr><th>四科</th><th>人物（字號）</th><th>事蹟摘要</th></tr></thead><tbody><tr><td rowspan=\"4\">德行</td><td>顏回（子淵）</td><td>安貧樂道，用之則行，舍之則藏；孔子稱其「不遷怒，不貳過」。早卒，孔子哭之慟。</td></tr><tr><td>閔損（子騫）</td><td>以孝著稱：「孝哉閔子騫，人不閒於其父母昆弟之言。」（二十四孝·單衣順母）</td></tr><tr><td>冉耕（伯牛）</td><td>有惡疾，孔子嘆：「斯人也，而有斯疾也！」</td></tr><tr><td>冉雍（仲弓）</td><td>「犂牛之子，騂且角，雖欲勿用，山川其舍諸？」（註：口才不佳）</td></tr><tr><td rowspan=\"2\">言語</td><td>宰予（子我）</td><td>長於專對，使於四方不辱君命；然《論語》載其言行多不美。</td></tr><tr><td>端木賜（子貢）</td><td>長於專對、善理財；孔子卒，子貢獨守廬墓六年。</td></tr><tr><td rowspan=\"2\">政事</td><td>冉求（子有／冉有）</td><td>多才藝；孔子稱「求也，千室之邑，百乘之家，可使為之宰也」。</td></tr><tr><td>仲由（子路／季路）</td><td>「由也，千乘之國，可使治其賦也。」性鄙，好勇力，志伉直。</td></tr><tr><td rowspan=\"2\">文學</td><td>言偃（子游）</td><td>嘗為武城宰，以禮樂為教（孔子戲之：「割雞焉用牛刀」）。</td></tr><tr><td>卜商（子夏）</td><td>孔子勉其為君子儒，無為小人儒；晚年居西河，喪子失明（「西河之痛」）。</td></tr></tbody></table>"}, {"label": "作者·補充｜軼事", "head": "孔子小檔案與軼事（作者補充）", "body": "<b>名丘</b>：孔子出生時，生而首上「圩頂」（圩，中間低而四周高起），所以取名孔丘。<br><b>至聖先師</b>：明世宗嘉靖九年（一五三○）追諡。<br><b>以「忠」、「恕」為行仁的方法</b>：《論語．里仁》中，曾子說：「夫子之道，忠恕而已矣。」孔子的中心思想「仁」便由「忠恕」貫徹實踐。《論語集註》中，朱熹曾言：「盡己之謂忠，推己之謂恕。」簡而言之，「忠」是竭盡自己的心力，「恕」是推己及人，「親親而仁民，仁民而愛物」、「老吾老以及人之老，幼吾幼以及人之幼」。「忠恕」促使「仁」有了具體落實的內容，有了明確執行的方法，同時奠定儒家愛人愛己，愛有等差的思想觀。<br><br><b>作者軼事</b><br>· 兒時玩樂：3歲父親叔梁紇卒，母親顏徵在帶著孔子搬到曲阜（魯國都城），並由母親教育。扮家家酒模仿儒生，演練禮儀。《史記・孔子世家》：為兒嬉戲，常陳俎豆，設禮容。<br>· 20歲娶妻、21歲生子孔鯉（字伯魚）。<br>· 30歲民間興學，開始收徒講學。55歲周遊列國、68歲返回魯國。回到魯國後繼續教育事業與整理文獻：刪《詩》、《書》，定《禮》、《樂》，著《春秋》。<br>· 71歲聽聞「西狩獲麟」（魯哀公14年春，西狩獲麟），嘆「吾道窮矣」，也在這年停止修訂《春秋》。<br>· 一生講學授徒無數。著名弟子有孔門四科十哲。"}], "intro": [{"label": "題解·課本", "head": "題解（課本）", "body": "本文選自《論語・先進》，為〈先進〉篇最後一章，原文無標題，標題乃編者所訂。「侍坐」，指陪侍於孔子座側。全文記錄孔子與學生的日常對話：從孔子引導學生暢談志向，看出學生的政治抱負及人格特質。在敞開心胸抒發情懷的對談中，孔子隨機啟發、循循善誘的教學方式，能感受到輕鬆卻充實的課堂氣氛；而孔子對曾皙的讚許，更透露出儒家淑世的精神與期許世界大同的襟懷。《論語》各章多為簡要語錄，然而本章卻超過四百字，結構完整，人物形象鮮明，在《論語》中極為特出。", "supList": [["循循善誘", "善於循序漸進地誘導別人。〈子罕〉：『夫子循循然善誘人，博我以文，約我以禮。』"]]}, {"label": "題解·補充｜《論語》簡介", "head": "《論語》簡介（題解補充）", "body": "《論語》共二十篇，始於〈學而〉，終於〈堯曰〉，記載孔子應答弟子及時人的對話，是一部語錄體經典。孔子逝世後，由孔子弟子及再傳弟子彙編成書。南宋朱熹將之與《孟子》、〈大學〉、〈中庸〉合為「四書」。「論」是「論纂」，「語」是「言語」；篇名多取每篇首章去除「子曰」後之二、三字，與內容不盡相關。〈先進〉為《論語》第十一篇，本課為其最後一章，也是全書篇幅最長的一章。", "supList": [["語錄體", "直接記錄或摘錄言論的一種文體。《孟子》、《墨子》、《莊子》亦見語錄；後世如《朱子語類》、《傳習錄》亦採語錄體。"], ["四書", "《論語》、《孟子》、〈大學〉、〈中庸〉。南宋朱熹合輯並作章句集注。"]]}, {"label": "題解·補充｜《論語》詳表", "head": "《論語》詳表（題解補充）", "body": "《漢書．藝文志》記載：「《論語》者，孔子應答弟子、時人，及弟子相與言而接聞於夫子之語也。當時弟子各有所記，夫子既卒，門人相與輯而論纂，故謂之《論語》。」<br><br><b>篇名與章數</b>：現在通行的《論語》是以東漢鄭玄〈注〉為準的《論語》，共計二十篇（起於〈學而〉，終於〈堯曰〉）。<table class=\"ly-table\"><tbody><tr><td>1.〈學而〉</td><td>2.〈為政〉</td><td>3.〈八佾〉</td><td>4.〈里仁〉</td></tr><tr><td>5.〈公冶長〉</td><td>6.〈雍也〉</td><td>7.〈述而〉</td><td>8.〈泰伯〉</td></tr><tr><td>9.〈子罕〉</td><td>10.〈鄉黨〉</td><td>11.〈先進〉</td><td>12.〈顏淵〉</td></tr><tr><td>13.〈子路〉</td><td>14.〈憲問〉</td><td>15.〈衛靈公〉</td><td>16.〈季氏〉</td></tr><tr><td>17.〈陽貨〉</td><td>18.〈微子〉</td><td>19.〈子張〉</td><td>20.〈堯曰〉</td></tr></tbody></table><br><table class=\"ly-table\"><thead><tr><th>項目</th><th>《論語》</th></tr></thead><tbody><tr><td>撰者</td><td>孔子弟子與再傳弟子（作者並非孔子本人）</td></tr><tr><td>異稱</td><td>亦可稱《論》或《語》，漢以後《論語》之名方漸趨確定。</td></tr><tr><td>數量</td><td>今本共20篇，分為上、下兩部</td></tr><tr><td>上部</td><td>計有〈學而〉、〈為政〉、〈八佾〉、〈里仁〉、〈公冶長〉、〈雍也〉、〈述而〉、〈泰伯〉、〈子罕〉、〈鄉黨〉等十篇。</td></tr><tr><td>下部</td><td>計有〈先進〉、〈顏淵〉、〈子路〉、〈憲問〉、〈衛靈公〉、〈季氏〉、〈陽貨〉、〈微子〉、〈子張〉、〈堯曰〉等十篇。</td></tr><tr><td>篇名</td><td>大抵取首章起始的二、三字作為篇名，篇名與該篇內容並無關聯。</td></tr><tr><td>中心思想</td><td>以「仁」為核心，顯現孔子政治、倫理、教育、道德修養等思想</td></tr><tr><td>內容</td><td>(1)關於個人人格修養的教言。(2)關於社會倫理的論述。(3)關於政治哲學的闡述。(4)關於人生哲學的闡述。(5)對孔門弟子及時人因材施教的問答。(6)對孔門弟子及古人、時人的批評。(7)孔子自述之言。(8)孔子的出處與日常行事。(9)孔門弟子對孔子的頌美與時人對孔子的評論。(10)孔門弟子的言論行事。</td></tr><tr><td>歷史地位</td><td>唐文宗時，列為十二經之一。南宋光宗時，列為十三經之一。南宋朱熹將《論語》、《孟子》、〈大學〉、〈中庸〉合稱四書，並為之作《四書章句集注》。</td></tr><tr><td>後世評論</td><td>北宋趙普嘗謂宋太宗曰：「臣有《論語》一部，以半部佐太祖定天下，以半部佐陛下致太平。」後人即以「半部《論語》治天下」評之。</td></tr></tbody></table><br><b>〈學而〉</b>：《論語》的第一篇，起於首句「學而時習之，不亦說乎？」而得名，此篇主要論述君子孝悌、仁人忠信等，朱子集注嘗說：「學者之先務也。」是成為君子的基本入門方法。<br><b>〈堯曰〉</b>：《論語》的最後一篇，起於首句「堯曰：『咨！爾舜！天之曆數在爾躬。允執其中。』」而得名，此篇記錄了堯舜湯武及孔子等人之言論，主要闡述聖人之道，以垂訓後世。<br><b>半部《論語》治天下</b>：北宋宰相趙普輔佐宋太祖統一全國，宋太祖逝世，宋太宗即位，曾有人認為趙普不學無術，僅懂《論語》一書，不適宜擔任宰相。趙普說明自己是以半部《論語》輔佐太祖平定天下，而今，則是以「半部《論語》治天下」。<br><b>後世士人必讀之書</b>：南宋朱熹將儒家的重要經典《論語》、《孟子》、〈大學〉、〈中庸〉集注成《四書章句集注》。元仁宗延祐二年時定為科舉考試的範疇，明清時亦奉為科舉之準則，對後世的學術、政治、思想、文化影響深遠。"}, {"label": "題解·補充｜語錄體", "head": "文體介紹：語錄體（題解補充）", "body": "<table class=\"ly-table\"><thead><tr><th>項目</th><th>說明</th></tr></thead><tbody><tr><td>定名</td><td>唐朝孔思尚的《宋齊語錄》定名。</td></tr><tr><td>定義</td><td>為古代散文體制的一種。記錄講學、傳教、論政及交際等活動之口語對話，偶或撰入人物形貌姿態以凸顯性格。</td></tr><tr><td>特色</td><td>短小精巧，以記錄對話為主，免去冗餘文藻。摘錄口語，形塑格言，常由大師弟子或後學輯錄名言警句，以傳後世。</td></tr></tbody></table><br><table class=\"ly-table\"><thead><tr><th>代表作品</th><th>說明</th></tr></thead><tbody><tr><td>《論語》</td><td>記載孔子及其弟子之言行，篇幅精要，語約意豐。</td></tr><tr><td>《朱子語類》</td><td>門人記錄朱熹學說言論以及弟子問答。</td></tr><tr><td>柏拉圖《理想國》（西方代表作品）</td><td>記載蘇格拉底與友人的滔滔雄辯，以對話傳遞哲思。</td></tr></tbody></table>"}, {"label": "寫作背景", "head": "寫作背景", "body": "孔門講學本在用世：子路長於治軍，冉有長於理財，公西華長於外交禮節，三人所學各有專長；曾皙則放情於山水、從容自樂於日常。就本章內容而言，師生討論言志，當在生活比較安穩的時期。<br><br><b>文化經典《論語》概述</b><br>《論語》成書背景源自禮樂崩壞的春秋末年，孔子無意出仕，進而撰書講學。由孔子弟子及再傳弟子編纂而成，主要記載孔子言行及與學生、時人的互動。孔子的生命經歷及其與弟子、時人的互動對話便成了《論語》一書的創作元素，孔子後學們藉此傳承其思想及精神。"}], "supplement": [{"label": "人物·四弟子", "head": "本課四位弟子", "body": "<b>子路</b>（仲由，字子路／季路，小孔子九歲）率直好勇、擅政事。<br><b>曾皙</b>（曾點，字皙，小孔子二十餘歲）狂放灑脫，與子曾參同為孔子弟子。<br><b>冉有</b>（冉求，字子有，小孔子二十九歲）謙和多才藝、擅政事。<br><b>公西華</b>（公西赤，字子華，小孔子四十二歲）熟習禮儀、擅外交。"}, {"label": "練習·四科十哲", "head": "孔門四科十哲（填空，點空格顯示答案）", "body": "<table class=\"ly-table\"><thead><tr><th><span class=\"jy-blank\" onclick=\"this.classList.toggle(&#39;show&#39;)\"><span class=\"jy-blank-ph\">&nbsp;&nbsp;&nbsp;&nbsp;</span><span class=\"jy-blank-ans\">德行</span></span></th><th>言語</th><th>政事</th><th>文學</th></tr></thead><tbody><tr><td>顏回</td><td>宰我</td><td>冉有</td><td><span class=\"jy-blank\" onclick=\"this.classList.toggle(&#39;show&#39;)\"><span class=\"jy-blank-ph\">&nbsp;&nbsp;&nbsp;&nbsp;</span><span class=\"jy-blank-ans\">子游</span></span></td></tr><tr><td><span class=\"jy-blank\" onclick=\"this.classList.toggle(&#39;show&#39;)\"><span class=\"jy-blank-ph\">&nbsp;&nbsp;&nbsp;&nbsp;</span><span class=\"jy-blank-ans\">閔子騫</span></span></td><td></td><td></td><td></td></tr><tr><td>冉伯牛</td><td><span class=\"jy-blank\" onclick=\"this.classList.toggle(&#39;show&#39;)\"><span class=\"jy-blank-ph\">&nbsp;&nbsp;&nbsp;&nbsp;</span><span class=\"jy-blank-ans\">子貢</span></span></td><td><span class=\"jy-blank\" onclick=\"this.classList.toggle(&#39;show&#39;)\"><span class=\"jy-blank-ph\">&nbsp;&nbsp;&nbsp;&nbsp;</span><span class=\"jy-blank-ans\">子路</span></span></td><td>子夏</td></tr><tr><td>仲弓</td><td></td><td></td><td></td></tr></tbody></table>"}], "lead": {"label": "課前·引導動機", "head": "課前引導", "body": "<b>學習重點</b><br>一、認識孔子的思想人格與《論語》的價值。<br>二、體會孔子培育人才的苦心和禮樂治國的真諦。<br>三、學習從言談舉止分析人物的性格與形象。<br>四、檢視自我能力，培養志趣與專長。<br><br><b>討論問題</b><br>· 你認為過去的「經典」之於現代，有什麼意義呢？<br>· 宋人趙普曾說「半部論語治天下」，若要你選出一本書來「治天下」，你會選擇哪一本呢？為什麼？"}, "appreciation": [{"label": "賞析", "head": "賞析（一）全文概述與層次", "body": "《論語》的篇章大多是文字簡短的語錄片段，本文是全書最長的篇章，記敘完整，涉及的人物眾多且個性鮮明，是呈現孔門教學情景最具代表性的一篇。<br><br>本文可分三個層次。從開頭至「則何以哉」寫孔子問志。從「子路率爾而對」至「吾與點也」寫弟子言志。從「三子者出」至文末，寫孔子評志。「志」是貫穿全文的核心，透過弟子「言志」來表現孔子「治國以禮」的中心思想，脈絡十分清楚。"}, {"label": "賞析", "head": "賞析（二）場景安排", "body": "文中場景的安排別具巧思：先以「侍坐」點出日常的生活場景，呈現師生間輕鬆和諧的氛圍；接著寫曾皙「鼓瑟希」，這才發現原來全場對話，從一開始便是在充滿音樂的美好情境中進行的；最後當「三子者出，曾皙後」，對話者從五人變成二人，展現文章繁簡疏密的變化，使情節充滿張力。"}, {"label": "賞析", "head": "賞析（三）人物刻畫", "body": "狀寫人物則靈動傳神：例如「率爾」之詞一出，子路形貌聲口立即如在眼前。曾皙開口前「鼓瑟希，鏗爾，舍瑟而作」，一連串細膩又連貫的動作，暗示曾皙與眾不同，其重要性比前三者也略勝一籌。寫孔子「喟然而嘆」，則使文章留下深長的況味。<br><br>文以對話形式精彩呈現師生的互動，人物的性情一覽無遺：子路的粗率豪邁，與冉有、公西華的謙恭謹慎恰成對比。當灑脫而自在的曾皙回答：「莫春者，春服既成，冠者五、六人，童子六、七人，浴乎沂，風乎舞雩，詠而歸。」這充滿詩意場景的理想境界，把全文推至最高潮。而孔子「吾與點也」的讚賞，既展現長者的風範，也隱約寄寓對禮樂教化、清平盛世的期待。"}]}, "keyRhetoric": [{"name": "倒裝", "pages": [{"sub": "賓語前置（否定句、疑問句）", "body": "否定句中代詞作賓語時前置：『不吾知也』＝『不知吾也』；『毋吾以也』＝『毋以吾也』。<br>疑問句中疑問代詞作賓語時前置：『則何以哉』＝『則以何哉』。"}, {"sub": "倒裝（其他）", "body": "『可使足民』＝『可使民足』。<br>本課倒裝多處，是理解文言語序的重點。"}]}], "workbook": {"title": "習作Ａ　第六課　論語選——子路曾皙冉有公西華侍坐", "sections": [{"kind": "table", "head": "壹 基礎認知站　一、字音探勘隊（每字 1 分，共 8 分）", "cols": ["", "字音", "詞語", "", "字音", "詞語"], "rows": [["1", "<span class='wk-a'>ㄕㄣˇ</span>", "夫子「哂」之", "2", "<span class='wk-a'>ㄙˋ</span>", "以「俟」君子"], ["3", "<span class='wk-a'>ㄍㄨㄢˋ</span>", "弱「冠」之年", "4", "<span class='wk-a'>ㄎㄨㄟˋ</span>", "「喟」然而嘆"], ["5", "<span class='wk-a'>ㄈㄨˇ　ㄍㄨㄢ</span>", "章「甫」玄「冠」", "6", "<span class='wk-a'>ㄈㄥˋ　ㄩˊ</span>", "「風」乎舞「雩」"]]}, {"kind": "table", "head": "二、字形領航員（每題 1 分，共 8 分）", "cols": ["", "字形", "詞語", "", "字形", "詞語"], "rows": [["1", "<span class='wk-a'>侍</span>", "「ㄕˋ」候", "2", "<span class='wk-a'>恃</span>", "「ㄕˋ」寵而驕"], ["3", "<span class='wk-a'>鏗</span>", "「ㄎㄥ」鏘有力", "4", "<span class='wk-a'>盛</span>", "太平「ㄕㄥˋ」世"], ["5", "<span class='wk-a'>躍</span>", "「ㄩㄝˋ」然紙上", "6", "<span class='wk-a'>耀</span>", "光芒閃「ㄧㄠˋ」"], ["7", "<span class='wk-a'>饉</span>", "饑「ㄐㄧㄣˇ」", "8", "<span class='wk-a'>謹</span>", "「ㄐㄧㄣˇ」慎"]]}, {"kind": "table", "head": "三、字義飛行傘（每題 2 分，共 8 分）", "cols": ["", "詞語", "答案"], "rows": [["例", "吾「與」點也", "(D)"], ["1", "「與」虎謀皮<br><span class='bk-note'>比喻所謀者與他人利害相牴觸，事情必辦不成</span>", "<span class='wk-a'>C</span>"], ["2", "時不我「與」<br><span class='bk-note'>比喻錯失時機，後悔莫及</span>", "<span class='wk-a'>A</span>"], ["3", "民胞物「與」<br><span class='bk-note'>視人民為同胞，以萬物為同類。比喻博愛</span>", "<span class='wk-a'>B</span>"], ["4", "選賢「與」能<br><span class='bk-note'>選拔賢德，將政事託付有能力的人</span>", "<span class='wk-a'>E</span>"]], "note": "請選出下列「　」內的正確字義代號。<br>參考選項：(A)等待　(B)同類　(C)向、對　(D)贊同、讚許　(E)通「舉」，推舉、選拔"}, {"kind": "table", "head": "四、國學常識解碼（每格 1 分，共 6 分）", "cols": ["", "內容"], "rows": [["孔子", "孔子思想以（1 <b class='wk-a'>仁</b>）為中心，（2 <b class='wk-a'>忠</b>）、（3 <b class='wk-a'>恕</b>）為行仁的方法，重視禮樂教化。他首開（4 <b class='wk-a'>平民</b>）教育之風，有教無類，因（5 <b class='wk-a'>材</b>）施教，後世尊稱為「（6 <b class='wk-a'>至聖先師</b>）」、「萬世師表」。"]]}, {"kind": "quiz", "head": "五、綜合理解練習（每題 5 分，共 40 分）", "items": [{"n": 1, "q": "下列各組「　」內的字，何者讀音相同？", "ans": "C", "opts": [["A", "千「乘」之國／騎「乘」機車", "ㄕㄥˋ／ㄔㄥˊ。"], ["B", "「莫」春時節／切「莫」驚慌", "ㄇㄨˋ／ㄇㄛˋ。"], ["C", "「比」及三年／天涯若「比」鄰", "ㄅㄧˋ。"], ["D", "吾「與」點也／唯求則非邦也「與」", "ㄩˇ／ㄩˊ。"]]}, {"n": 2, "q": "(甲)如或知爾，則何「以」哉／「以」吾一日長乎爾　(乙)「鼓」瑟希／敲鑼打「鼓」　(丙)「比」及三年／遠「比」不上　(丁)方六、七十，「如」五、六十／「如」其禮樂，以俟君子　(戊)可使有勇，且知「方」也／「方」六、七十。以上各組「　」內的字，意義相同的選項是：", "ans": "D", "opts": [["A", "(甲)(丙)", ""], ["B", "(乙)(丁)(戊)", ""], ["C", "(甲)(乙)(戊)", ""], ["D", "全不同", "(甲)用／因為。(乙)彈奏／樂器。(丙)等到／比較。(丁)或者／至於。(戊)此指禮義／計算面積的用語。"]]}, {"n": 3, "q": "下列關於字詞與通同字的說明，何者不可互相替換？", "ans": "B", "opts": [["A", "「莫」春：通「暮」", ""], ["B", "鼓瑟「希」：通「晰」", "通「稀」。晰：清楚、明白。"], ["C", "「舍」瑟而作：通「捨」", ""], ["D", "唯求則非邦也「與」：通「歟」", ""]]}, {"n": 4, "q": "下列文句，何者倒裝之後意思與原意相同？", "ans": "B", "opts": [["A", "毋吾以也：即「吾毋以也」", "即「毋以吾也」。"], ["B", "則何以哉：即「則以何哉」", ""], ["C", "以吾一日長乎爾：即「吾以一日長乎爾」", "即「以吾長乎爾一日」。"], ["D", "異乎三子者之撰：即「三子者之撰異乎」", "無此說法。"]]}, {"n": 5, "q": "〈子路曾皙冉有公西華侍坐〉全文以對話形式精彩呈現師生的互動，人物的性情一覽無遺。下列關於人物與性情的說明，何者正確？", "ans": "A", "opts": [["A", "冉有待老師問而後答，可見個性較為謙讓被動；就其回答的內容，亦見其相對退讓保守的個性", ""], ["B", "曾皙對於外交之事，不說自己「可以」，而是說自己願意「學習」，處處可見他身為晚輩的客氣與敬慎", "曾皙→公西華。"], ["C", "從公西華搶先回答孔子問題，足見其個性率直衝動，孔子認為公西華談以禮治國，自己卻毫不謙讓，因此「哂之」", "公西華→子路。"], ["D", "子路可視為瀟灑的性格，先點出自己的志向異於前三者，卻仍是自信敢言；而從嚮往與自然合而為一的志向中，亦可看見其不受世俗拘束的從容性格", "子路→曾皙。"]]}, {"n": 6, "q": "關於本文的說明，下列何者正確？", "ans": "A", "opts": [["A", "本文選自《論語．先進》篇", ""], ["B", "以「侍坐」點出日常的生活場景，呈現師生間拘謹嚴肅的氛圍", "拘謹嚴肅→輕鬆和諧。"], ["C", "「喟然」是貫穿全文的核心，透過弟子「言志」來表現孔子的中心思想", "「喟然」→「志」。"], ["D", "孔子「吾與赤也」的讚賞，既展現長者的風範，也隱約寄寓對禮樂教化的期待", "文中孔子「吾與點也」的讚賞，即表達最為欣賞曾皙的志向。"]]}, {"n": 7, "q": "下列關於《論語》的說明，何者正確？", "ans": "C", "opts": [["A", "由孔子與弟子及再傳弟子輯論而成", "由孔子弟子及再傳弟子輯論而成。"], ["B", "共二十篇，第一篇為〈學而〉，最終篇為〈盡心〉", "最終篇為〈堯曰〉。"], ["C", "擷取每篇首章第一句中二或三字為篇名，篇名與內容無關", ""], ["D", "南宋朱熹將《論語》與《孟子》、《大學》、《孝經》合為「四書」", "《論語》與《孟子》、《大學》、《中庸》合為「四書」。"]]}, {"n": 8, "q": "(甲)觀於海者難為水，道若江河，隨地可成洙泗／譬猶天之不可階，聖如日月，普天皆有春秋　(乙)彭澤非我榮，折腰信為辱。歸來北窗下，復採東籬菊　(丙)修《詩》《書》／作《春秋》，含笑，栽植／那七十二株等待茂盛的杏樹　(丁)三千弟子標青史，萬代先生號素王。蕭索風高洙泗上，秋山明月夜蒼蒼。以上作品，何者指稱孔子？", "ans": "A", "opts": [["A", "(甲)(丙)(丁)", "(甲)由「洙泗、春秋」可判斷為孔子。洙泗：孔子聚徒講學於洙水和泗水。山東曲阜孔廟聯。(乙)由「彭澤、折腰、東籬菊」判斷為陶淵明。吳筠〈陶徵君〉。(丙)「修《詩》《書》／作《春秋》」為孔子所為，「七十二株等待茂盛的杏樹」象徵孔子七十二位賢弟子。渡也〈麟〉。(丁)素王：古人以為孔子雖無官位，但修《春秋》以制明王之法，故稱孔子為素王。劉滄〈經曲阜城〉。<br>語譯：(乙)彭澤縣令不是我的榮耀，彎腰下拜實在是恥辱。辭官歸來高臥北窗下，又在東籬採菊花。(丁)三千弟子的姓名留載在史書上，萬代先生被稱為有王者之道但不居王位的人。孔子聚徒講學的洙水和泗水一片風高荒涼，明月照著秋山夜空蒼茫。"], ["B", "(乙)(丙)(丁)", ""], ["C", "(甲)(乙)(丁)", ""], ["D", "(甲)(乙)(丙)", ""]]}]}, {"kind": "read", "head": "貳 進階實力站　一、閱讀測驗（每題 3 分，共 18 分）(一)", "appraise": "本文從《論語》各篇舉證中肯定了孔子幽默與近人情的特質，強調孔子親切、活潑、自然的一面。作者並藉此反思程、朱等宋代儒者論述孔子的問題，宋儒因為以道學面來論述孔子，為了保有孔子聖人形象而有了先入為主的成見，也無法感受孔子真實可親的本色。", "passage": "(甲)　　孔子自然是幽默的。只惜前人理學氣太厚，不曾懂得。桓魋<sup>①</sup>一類人想要害孔子，孔子：「桓魋其如予何？」的話，雖然表示自信力甚強，總也是自得自適君子不憂不懼一種氣派。他那安詳自適的態度，最明顯的例，是在陳絕糧一段。門人都已出怨言了，孔子獨弦歌不衰，不改那種安詳幽默的態度。他三次問門人：「我們一班人，不三不四，非牛非虎，流落到這田地，為什麼呢？」這是我所最愛的一段，也是使我們最佩服孔子的一段。有一次，孔子與門人相失於路上。後來有人在東門找到孔子，說他的相貌，並說他像一條「喪家犬」。孔子聽見說：「別的我不知道。至於像一條喪家狗，倒有點像。」<br><br>　　須知孔子是最近人情的，他是恭而安，威而不猛，並不是道貌岸然，冷酷酷拒人於千里之外。但是到了程、朱諸宋儒的手中，孔子的面目就改了。以道學面孔論孔子，必失孔子原來的面目。凡遇到孔子活潑潑所為未能完全與道學理想符合，或言宋儒之所不敢言，或為宋儒之不敢為，崔東壁就斷定是「聖人必不如此」，而斥為偽作，或後人附會。顧頡剛也曾表示對崔東壁不滿處：「他信仰經書和孔、孟的氣味都嫌太重，糅雜了許多先入為主的成見。」<div class='aq-src'>註：①魋：音ㄊㄨㄟˊ。</div><div class='aq-src'>（節錄自林語堂〈論孔子的幽默〉）</div><br>(乙)　　孺悲欲見孔子，孔子辭以疾。將命者出戶，取瑟而歌，使之聞之。<div class='aq-src'>（《論語．陽貨》）</div><details style='margin-top:10px'><summary>(乙)語譯</summary>孺悲要求會見孔子，孔子要門人推辭有病而拒絕接見。傳話的人剛走出門口，孔子便故意拿出瑟彈奏並唱起歌來，讓孺悲聽見。</details>", "items": [{"n": 1, "q": "依據(甲)文所述，下列何者是作者所認為「宋人論孔」的問題？", "ans": "D", "opts": [["A", "認為聖人所為，常人必不敢為", "宋人論孔以道學面討論，因此對於孔子同於常人的活潑、幽默、近於人情部分，予以否定，並認為「常人所為，聖人必不敢為」。"], ["B", "看重研究討論，容易人云亦云", "(B)(C)信仰經書和孔、孟的氣味都嫌太重，糅雜了許多先入為主的成見。"], ["C", "過於講究經典考證，不敢妄下結論", "(B)(C)信仰經書和孔、孟的氣味都嫌太重，糅雜了許多先入為主的成見。"], ["D", "以道學論孔子，失去孔子原來的面目", ""]]}, {"n": 2, "q": "孔子善於針對不同學生的個性而因材施教，請判斷在(乙)文中，孔子所採用的教育方法應為：", "ans": "A", "opts": [["A", "不屑之教", "孔子藉由讓孺悲知道老師不願（屑）見他，來引發他的反省之心。"], ["B", "言詞鼓勵", ""], ["C", "啟發教育", ""], ["D", "幽默教導", ""]]}, {"n": 3, "q": "(甲)(乙)二文皆提到孔子生活中所展現的各種面貌，下列關於孔子態度的說明，何者正確？", "ans": "C", "opts": [["A", "在陳絕糧，門人怨言不斷，孔子藉弦歌不衰，平靜自己的悲傷絕望", "孔子獨弦歌不衰，不改安詳幽默的態度。"], ["B", "孺悲欲見孔子，孔子拒絕並「取瑟而歌，使之聞之」，展現他有仇必報的一面", "展現他活潑的一面。"], ["C", "桓魋一類人想要害孔子，孔子說：「桓魋其如予何？」的話，表示自信力甚強，也是不憂不懼的一種氣派", ""], ["D", "孔子與門人相失於路上，後來有人在東門找到孔子，並說他的相貌像「喪家犬」；孔子聽見後極為憤怒，感嘆時不我與", "孔子聽見後不以為意並表示認同。"]]}]}, {"kind": "read", "head": "一、閱讀測驗 (二)", "appraise": "本詩旨在勾勒孔子的聖人形象，透過頻頻回頭的動作，道出孔子內心的牽掛與眷戀。作者以層遞修辭開展孔子的聖人情懷，先敘私情，再敘家國之憂，終敘淑世志業，於是一個有血有肉的聖人便矗立在我們眼前。", "passage": "　　走過曲阜斜坡，仲尼曾經三次回頭；／一次為顏淵、子路、曾參、宰我；／一次為孔鯉、孔伋。／另一次為門口那棵蒼勁的古柏。<br><br>　　走過魯國開闊的平疇<sup>①</sup>，仲尼只回了兩次頭：／一次為遍地青柯不再翠綠，遍地□□不再黃熟；／一次為東逝的□□從來不知回頭而回頭，／回頭止住那一顆忍不住的淚沿頰邊而流。<br><br>　　走過人生仄徑<sup>②</sup>時，仲尼曾經最後一次回頭：／看天邊那一個仁字，還有那個人在左邊，／撐天上的那一橫、地上的那一橫；／留個寬廣任人行走！<div class='aq-src'>註：①平疇：平原田地。疇，音ㄔㄡˊ。②仄徑：小路。</div><div class='aq-src'>（蕭蕭〈仲尼回頭〉）</div>", "items": [{"n": 4, "q": "依據文意推斷，第二節□□中的字詞，依序應為下列何者？", "ans": "B", "opts": [["A", "野花／孩童", ""], ["B", "麥穗／流水", "由「遍地」、「黃熟」判斷，以「麥穗」最恰當。「東逝」、「不知回頭」的「流水」象徵時間，最切合文意。"], ["C", "牛羊／雲朵", ""], ["D", "荒草／野雁", ""]]}, {"n": 5, "q": "詩文中多次用「回頭」這樣的動作，其目的是凸顯孔子的何種想法？", "ans": "B", "opts": [["A", "不願同流合汙的堅持", ""], ["B", "內心放不下的牽掛與眷戀", "孔子不斷的「回頭」乃因內心放不下對師生情誼、淑世志業的牽掛與眷戀，也有著時間匆匆而去，卻時不我待的無奈。"], ["C", "在仕與隱之間的徬徨與掙扎", ""], ["D", "周旋於魯國與列國間的兩難", ""]]}, {"n": 6, "q": "「仲尼曾經最後一次回頭：／看天邊那一個仁字，還有那個人在左邊，／撐天上的那一橫、地上的那一橫；／留個寬廣任人行走！」關於此段文句的敘述，下列何者<u>錯誤</u>？", "ans": "B", "opts": [["A", "詩中詮釋仁字的寫法和結構", ""], ["B", "提出忠、恕是行仁的最佳方法", "並未提到。"], ["C", "點出仁是孔子的中心思想和一生的堅持", ""], ["D", "強調人間最寬廣的大道是仁，勉勵人人皆應行仁", ""]]}]}, {"kind": "table", "head": "二、趣味文學體驗（每題 3 分，共 12 分）", "cols": ["", "答案", "說明"], "rows": [["1", "<span class='wk-a'>A</span>", "(A)發憤忘食：專心學習或工作以致忘記吃飯。"], ["2", "<span class='wk-a'>D</span>", "(D)暴虎馮河：指空手與虎搏鬥，不靠舟船渡河。比喻人有勇而無謀。暴，徒手搏鬥。馮，徒步渡河。"], ["3", "<span class='wk-a'>C</span>", "(C)舉一反三：指列舉一例而能曉喻其他各事。"], ["4", "<span class='wk-a'>B</span>", "(B)待價而沽：比喻人等待機會，為世所用。"]], "note": "以下畫面皆出自《論語》，請依情境將正確的成語選項答案填入空格中。<br>參考選項：(A)發憤忘食　(B)待價而沽　(C)舉一反三　(D)暴虎馮河<img src='img/侍坐/ae3321d05b17643a.png' style='max-width:100%;display:block;margin:10px auto;width:680px' alt=''>"}, {"kind": "table", "head": "參 挑戰加分站（不計分）", "cols": ["", "問題", "答案", "說明"], "rows": [["1", "因為不遷怒、不貳過，所以被後人稱為「復聖」。且孔子讚其安貧樂道，曰：「賢哉□也！一簞食，一瓢飲，在陋巷。人不堪其憂，□也不改其樂。賢哉□也！」", "<span class='wk-a'>E</span>", "多麼賢良啊，顏回！吃的是一小簍飯，喝的是一瓢湯水，住在陋巷裡，別人忍受不了這種貧苦，而顏回卻不改變他好學的樂趣。多麼賢良啊，顏回！《論語．雍也》"], ["2", "能言善道，善做生意，為孔門弟子中最富有者，後代也以「端木」做為商人代稱。", "<span class='wk-a'>A</span>", ""], ["3", "能言善辯，因白天睡覺而遭孔子責罵：「朽木不可雕也，糞土之牆不可杇也。」", "<span class='wk-a'>B</span>", "腐朽的木頭不可以用來雕刻，用汙穢的泥土築成的牆無法加以粉刷。《論語．公冶長》"], ["4", "重義輕財、勇敢熱情，極富正義感，曾說「千乘之國，比及三年，可使有勇，且知方也」", "<span class='wk-a'>D</span>", ""], ["5", "熟習禮儀，擅長外交，曾說「宗廟之事，如會同，端章甫，願為小相焉」。", "<span class='wk-a'>C</span>", ""]], "note": "電影首映會：導演李小安預備將孔子及其弟子的傳奇故事拍為電影，劇中孔門弟子的角色力邀人氣偶像團體「G5」演出。今日主持人為了宣傳，特別請五位成員穿著劇中戲服出席記者會，並設計了一系列的問題。根據下列問題，猜猜他是誰？並將正確代號填入答案格中。<br>(A)子貢　(B)宰我　(C)公西華　(D)子路　(E)顏淵<img src='img/侍坐/b0762764598ddd20.png' style='max-width:100%;display:block;margin:10px auto;width:460px' alt=''>"}]}, "aHand": {"title": "第一部分：非選擇題（共 22 分）", "secs": [{"h": "一、字音字形（每題 2 分，共 12 分）", "items": [["1", "千「乘」之國", "ㄕㄥˋ"], ["2", "以「俟」君子", "ㄙˋ"], ["3", "夫子「哂」笑", "ㄕㄣˇ"], ["4", "「ㄩㄝˋ」然紙上", "躍"], ["5", "「ㄎㄨㄟˋ」然嘆曰", "喟"], ["6", "略勝一「ㄔㄡˊ」", "籌"]]}, {"h": "二、解釋（每題 2 分，共 10 分）", "items": [["1", "率爾", "輕率的樣子，此有搶先之意。"], ["2", "加之以「師旅」", "軍隊。"], ["3", "「比及」三年", "等到。"], ["4", "宗廟之事", "此指諸侯祭祀祖先的大典。"], ["5", "會同", "指諸侯朝覲天子或諸侯會盟之事。"]]}]}, "aQuiz": [{"n": 1, "ans": "A", "stem": "下列文句，何者用字完全正確", "opts": [["A", "由於連年饑饉，民不聊生，人心思變，王朝岌岌可危"], ["B", "志玲的皮膚光滑白析，歲月沒有在她臉上留下任何痕跡"], ["C", "他的思想清楚而有條理，說起道理來硜鏘有力，令人信服"], ["D", "教學方式沒有熟是熟非，重要的是學生適合哪一種方法"]], "exp": "(B)白「皙」。(C)「鏗」鏘有力。(D)「孰」是「孰」非。", "trans": "", "psg": "", "need_img": false, "per": {"B": "白「皙」。", "C": "「鏗」鏘有力。", "D": "「孰」是「孰」非。"}}, {"n": 2, "ans": "B", "stem": "下列各組「　」中的字，何者意義相同", "opts": [["A", "加之以師旅，「因」之以饑饉／未若柳絮「因」風起"], ["B", "宗廟之事，「如」會同，端章甫／方六、七十，「如」五、六十"], ["C", "鼓瑟希，鏗爾，「舍」瑟而作／退避三「舍」"], ["D", "如或知爾，則何「以」哉／「以」吾一日長乎爾，毋吾以也"]], "exp": "(A)接連／憑藉。(B)或者。(C)放下／三十里。退避三舍：比喻遇到實力很強的對手，為避免正面衝突折損太多，乃主動讓步，不與人爭。(D)用／因為。", "trans": "(A)又受到外敵的侵略，接著又鬧饑荒／不如說像柳絮憑藉風勢在空中飄揚吧！《世說新語．詠絮之才》。(B)在諸侯祭祀或朝覲、會盟的典禮上，我願意穿著禮服，戴著禮帽／一個土地面積六、七十里見方或五、六十里見方的小國家。(C)瑟聲漸歇，接著鏗然一聲，放下瑟，站起來。(D)如果有人了解你們，那你們用什麼來表現自己的才能／不要因為我的年紀比你們稍大，就不好意思說出自己的志向。", "psg": "", "need_img": false, "per": {"A": "接連／憑藉。", "B": "或者。", "C": "放下／三十里。退避三舍：比喻遇到實力很強的對手，為避免正面衝突折損太多，乃主動讓步，不與人爭。", "D": "用／因為。"}}, {"n": 3, "ans": "A", "stem": "下列各句，何者有冗贅字詞", "opts": [["A", "子路直接不加思索的回答說：我可以協助練兵"], ["B", "公西華羨慕無拘無束的生活，想到河邊自在吹風"], ["C", "冉有是位能文能武的通才，帶兵征戰與財務計算都難不倒他"], ["D", "曾皙情緒起伏大，曾暴力毆傷曾參，也曾雍容自若鼓瑟"]], "exp": "(A)「直接」與「不加思索」意義重疊，不應重複。", "trans": "", "psg": "", "need_img": false, "per": {"A": "「直接」與「不加思索」意義重疊，不應重複。"}}, {"n": 4, "ans": "A", "stem": "國文老師請四位學生用出自《論語》的成語造句，下列「　」內運用最適當的是", "opts": [["A", "AI 時代的來臨，我們應當以「君子不器」自勉，主動學習不斷進步"], ["B", "面對這件棘手的案件，處理時要仔細謹慎，「暴虎馮河」方能成功"], ["C", "王律師能說善道，每次發表言論都「巧言令色」，滔滔不絕"], ["D", "一個人做事如果「行不由徑」，會受到大家的鄙視"]], "exp": "(A)比喻君子體用兼備，不只一才一藝而已。(B)比喻人有勇而無謀。可改為「兢兢業業」（形容謹肅恐懼，認真小心）。(C)話說得很動聽，臉色裝得很和善，可是一點也不誠懇。不適合形容口才一流。可改為「口若懸河」（形容能言善辯）。(D)走路不走捷徑，比喻行事光明正大。可改為「投機取巧」（利用時機，獲取利益）。", "trans": "", "psg": "", "need_img": false, "per": {"A": "比喻君子體用兼備，不只一才一藝而已。", "B": "比喻人有勇而無謀。可改為「兢兢業業」（形容謹肅恐懼，認真小心）。", "C": "話說得很動聽，臉色裝得很和善，可是一點也不誠懇。不適合形容口才一流。可改為「口若懸河」（形容能言善辯）。", "D": "走路不走捷徑，比喻行事光明正大。可改為「投機取巧」（利用時機，獲取利益）。"}}, {"n": 5, "ans": "A", "stem": "若要使下文的理路連貫有序，①、②、③、④、⑤最適當的排列應是：", "opts": [["A", "④②⑤①③"], ["B", "⑤②④③①"], ["C", "④⑤③①②"], ["D", "④②①③⑤"]], "exp": "依據第一句可知，創新、超越自己是本質，而自我超越時要有明確方向，否則只是白費工夫，故先接④②。接下來提出「學習的目的」為後半段的主語，而「助人實現生命」是對「學習的目的」的說明，故再接⑤①。最後③「讓生命得到安頓」可與末句「這種樂趣是內發的與永恆的」相承接。", "trans": "", "psg": "　　人的本質在於創新，可以不斷超越自己。　①助人實現生命的要求，②否則只是盲目浪費時光與熱情。③在學習中逐漸讓生命得到安頓，④但是超越必須以明確的方向為指引，⑤學習的目的是為人生定位，　這種樂趣是內發的與永恆的。<div class='aq-src'>（傅佩榮〈學習的樂趣〉）</div>", "need_img": false, "per": {"A": "依據第一句可知，創新、超越自己是本質，而自我超越時要有明確方向，否則只是白費工夫，故先接④②。接下來提出「學習的目的」為後半段的主語，而「助人實現生命」是對「學習的目的」的說明，故再接⑤①。最後③「讓生命得到安頓」可與末句「這種樂趣是內發的與永恆的」相承接。"}}, {"n": 6, "ans": "C", "stem": "為了音律上的需要，或為引起讀者注意，強調某些語詞，刻意破壞句子原本順序，顛倒文法邏輯詞序的修辭法，稱為「倒裝」。下列「　」內的文句皆使用了倒裝，何者還原後的詞語順序<b>錯誤</b>", "opts": [["A", "「主義是從」→從主義"], ["B", "居則曰：「不吾知也！」→不知吾也"], ["C", "如或知爾，「則何以哉」→則以哉何"], ["D", "以吾一日長乎爾，「毋吾以也」→毋以吾也"]], "exp": "(C)則以何哉。", "trans": "(B)平日你們總是說：「沒有人了解我！」(C)如果有人了解你們，那你們用什麼來表現自己的才能？(D)不要因為我的年紀比你們稍大，就不好意思說出自己的志向。", "psg": "", "need_img": false, "per": {"C": "則以何哉。"}}, {"n": 7, "ans": "D", "stem": "「轉品」是指改變詞語原本詞性，使意義表達更生動豐富的修辭手法。下列「　」中的字，何者<b>未使用</b>「轉品」", "opts": [["A", "「鼓」瑟希，鏗爾，舍瑟而作"], ["B", "浴乎沂，「風」乎舞雩，詠而歸"], ["C", "巫、醫、樂師、百工之人，君子不「齒」"], ["D", "為國以禮，其言不讓，是故「哂」之"]], "exp": "(A)彈奏，名詞轉動詞。(B)吹風乘涼，名詞轉動詞。(C)並列，名詞轉動詞。(D)微笑，動詞。", "trans": "(A)瑟聲漸歇，接著鏗然一聲，放下瑟，站起來。(B)到沂水邊洗洗澡，在求雨的祭壇上吹風乘涼，然後唱著歌回家。(C)巫師、醫生、樂師和從事各種技藝的人，君子不屑和他們並列。韓愈〈師說〉。(D)治國應當講禮，子路的話毫不謙讓，所以我笑他。", "psg": "", "need_img": false, "per": {"A": "彈奏，名詞轉動詞。", "B": "吹風乘涼，名詞轉動詞。", "C": "並列，名詞轉動詞。", "D": "微笑，動詞。"}}, {"n": 8, "ans": "B", "stem": "孔子要學生分享志向前，先說「以吾一日長乎爾，毋吾以也」其原因為何", "opts": [["A", "強調輩分尊卑，讓回話的依序方式由年紀大小排列"], ["B", "化解師生間的拘謹，緩和氣氛使學生說出真正的想法"], ["C", "去除學生戒慎恐懼的心態，但仍必須依照尊卑禮儀說話"], ["D", "強調學生須以自己為楷模，不要忘記求學拜師的初衷"]], "exp": "", "trans": "題幹語譯：不要因為我的年紀比你們稍大，就不好意思說出自己的志向。", "psg": "", "need_img": false, "per": {}}, {"n": 9, "ans": "D", "stem": "孔子問曾皙志向，曾皙在開口前「鼓瑟希，鏗爾，舍瑟而作」，一連串細膩又連貫的動作說明了曾皙的與眾不同。關於這段動作的敘述，下列說明何者最適當", "opts": [["A", "「鏗爾」形容樂音綿延不絕，暗示曾皙期待寧靜祥和的大同世界"], ["B", "展現曾皙對自己回答的自信"], ["C", "顯示曾皙在這場對話中從一開始就心不在焉，原本不願發言"], ["D", "由「舍瑟而作」可以看出曾皙閒雅恭敬的態度"]], "exp": "(A)「鏗爾」形容結束彈奏瑟音終止的聲響，非綿延不絕的聲響。(B)展現曾皙不疾不徐的從容形象。(C)文中未見曾皙心不在焉不願發言的線索。", "trans": "題幹語譯：瑟聲漸歇，接著鏗然一聲，放下瑟，站起來。", "psg": "", "need_img": false, "per": {"A": "「鏗爾」形容結束彈奏瑟音終止的聲響，非綿延不絕的聲響。", "B": "展現曾皙不疾不徐的從容形象。", "C": "文中未見曾皙心不在焉不願發言的線索。"}}, {"n": 10, "ans": "C", "stem": "〈子路曾皙冉有公西華侍坐〉一文中，孔子要學生分享志願，子路回答：「可使有勇，且知方也。」冉有回答：「可使足民。如其禮樂，以俟君子。」公西華回答：「願為小相焉。」下列解釋何者最適當", "opts": [["A", "在國家艱困危難之際，子路使人民擁有勇武之道並制定治國方針"], ["B", "冉有說「如其禮樂，以俟君子」是因他專長為民生經濟，不懂禮樂教化之事"], ["C", "三位弟子均展現淑世精神"], ["D", "依說話的自信程度排序為子路、公西華、冉有"]], "exp": "(A)「方」指禮義，子路認為可以使人民有武勇且知禮義。(B)冉有是為表達謙遜，非不懂禮樂教化。(D)自信程度依序應為子路、冉有、公西華。", "trans": "題幹語譯：可使人民有勇氣，並且懂得禮義／可以使人民富足。至於禮樂教化，就只有等待更有才德的君子了／做個贊禮的小相。", "psg": "", "need_img": false, "per": {"A": "「方」指禮義，子路認為可以使人民有武勇且知禮義。", "B": "冉有是為表達謙遜，非不懂禮樂教化。", "D": "自信程度依序應為子路、冉有、公西華。"}}, {"n": 11, "ans": "C", "stem": "〈子路曾皙冉有公西華侍坐〉一文中，孔子讚許曾皙的原因為何", "opts": [["A", "其品德勝於其他三人"], ["B", "欣羨曾皙悠然自適的個性"], ["C", "志向隱含對清平盛世的期待"], ["D", "讚嘆曾皙有感化他人的能力"]], "exp": "(C)孔子欣賞其閒適而不失理想之志，非以德行高下為準。", "trans": "", "psg": "", "need_img": false, "per": {"C": "孔子欣賞其閒適而不失理想之志，非以德行高下為準。"}}, {"n": 12, "ans": "D", "stem": "關於〈子路曾皙冉有公西華侍坐〉一文的文句說明，下列敘述何者最適當", "opts": [["A", "（曾皙）對曰：「異乎三子者之撰。」——寫曾皙孤傲自賞、與人不諧的個性"], ["B", "子路：「由也為之，比及三年，可使有勇，且知方也。」——寫子路偏尚勇力、鼓勵戰鬥的個性"], ["C", "（公西華）：「非曰能之，願學焉。」——寫公西華能力不足，但學習意願強烈"], ["D", "子曰：「何傷乎？亦各言其志也。」——寫孔子親切沒有架子，並善於鼓勵學生發言"]], "exp": "(A)寫曾皙特立獨行，與眾不同的性格。(B)寫子路充滿自信。(C)寫公西華謙恭謹慎的性格。", "trans": "(A)我和他們三位所講的不同。(B)讓我來治理，等到三年後，可使人民有勇氣，並且懂得禮義。(C)不敢說能做好，只是希望能有學習的機會。(D)有什麼關係呢？不過是各自談談志向罷了。", "psg": "", "need_img": false, "per": {"A": "寫曾皙特立獨行，與眾不同的性格。", "B": "寫子路充滿自信。", "C": "寫公西華謙恭謹慎的性格。"}}, {"n": 13, "ans": "A", "stem": "在〈子路曾皙冉有公西華侍坐〉一則中，我們不僅可以從中了解孔子與弟子之間的互動，也可窺知孔子的想法。下列解釋何者<b>較不適當</b>", "opts": [["A", "「夫子喟然嘆曰：吾與點也！」喟然的原因是孔子勉強找到一個志向相近的弟子"], ["B", "「赤也為之小，孰能為之大？」代表孔子對自己學生才能的肯定"], ["C", "「安見方六、七十，如五、六十，而非邦也者？」可見冉求個性謙遜，孔子仍然肯定其治國理念"], ["D", "「為國以禮，其言不讓，是故哂之。」認為子路以禮治國卻不懂謙讓"]], "exp": "(A)喟然是因「世衰道微」。孔子「邦有道，則仕；邦無道，則可卷而懷之」（語譯：國家有道時，就應該出來任官，協助治理；國家無道時，就應該退隱，把理想抱負深藏於心，不輕易展露）但「卷而懷之」非孔子初衷，故喟然長嘆。", "trans": "(A)孔子嘆息說：「我贊同點所說的呀！」(B)如果公西華只能做贊禮的小相，又有誰能做大相呢？(C)怎麼見得六、七十里見方或五、六十里見方的地方，不算是一個國家呢？(D)治國應當講禮，子路的話毫不謙讓，所以我笑他。", "psg": "", "need_img": false, "per": {"A": "喟然是因「世衰道微」。孔子「邦有道，則仕；邦無道，則可卷而懷之」（語譯：國家有道時，就應該出來任官，協助治理；國家無道時，就應該退隱，把理想抱負深藏於心，不輕易展露）但「卷而懷之」非孔子初衷，故喟然長嘆。"}}, {"n": 14, "ans": "C", "stem": "關於〈子路曾皙冉有公西華侍坐〉的敘述，下列敘述何者最適當", "opts": [["A", "以小說形式呈現內容，並以孔子的詢問開頭、評論作結，首尾呼應"], ["B", "文中以孔子對弟子志向的評論，展現學生特質"], ["C", "全文以「禮」與「讓」表現出孔子治國的基礎"], ["D", "文中描寫四位弟子的志向依序排列為最劣至最優"]], "exp": "(A)屬語錄體，非小說，以對話形式呈現內容。(B)藉寫每個學生的言談舉止及應對，展現個人特質。(D)文中前三位弟子不分優劣。", "trans": "", "psg": "", "need_img": false, "per": {"A": "屬語錄體，非小說，以對話形式呈現內容。", "B": "藉寫每個學生的言談舉止及應對，展現個人特質。", "D": "文中前三位弟子不分優劣。"}}, {"n": 15, "ans": "C", "stem": "「子適衛，冉有僕。子曰：『庶矣哉！』冉有曰：『既庶矣，又何加焉？』曰：『富之。』曰：『既富之，又何加焉？』曰：『教之。』」（《論語．子路》）依據上文，下列解釋最適當的選項是", "opts": [["A", "「庶矣哉」是指衛國人口稀少"], ["B", "孔子施政理念與冉求「方六、七十，如五、六十，求也為之，比及三年，可使足民」相同"], ["C", "孔子藉衛國人民眾多的榮盛景況，說明治國應先富後教"], ["D", "文中，冉有以層遞法追問使國家人口增加的方法"]], "exp": "(A)衛國人口眾多。(B)冉有治民首重「民生」，孔子施政先富後教。(D)冉有詢問孔子在人口繁盛之後應如何治理國家，並非想詢問使國家人口增加的方法。", "trans": "孔子前往衛國，冉有替他駕馬車。孔子說：「衛國人口眾多！」冉有說：「人口增加了，進一步要做什麼？」孔子說：「讓人民富有。」冉有說：「人民富足了，進一步要做什麼？」孔子說：「教化他們。」(B)一個土地面積六、七十里見方或五、六十里見方的小國家，讓我來治理，等到三年後，可以使人民富足。", "psg": "", "need_img": false, "per": {"A": "衛國人口眾多。", "B": "冉有治民首重「民生」，孔子施政先富後教。", "D": "冉有詢問孔子在人口繁盛之後應如何治理國家，並非想詢問使國家人口增加的方法。"}}, {"n": 16, "ans": "B", "stem": "某天老師帶領同學參觀歷史文物陳列館，看到子路「冠雞佩豚」的獨特造型（如下圖）。司馬遷在《史記．仲尼弟子列傳》就說：「子路性鄙，好勇力，志伉直，冠雄雞，佩豭豚。」〈集解〉：「二物皆勇，子路好勇，故冠帶之。」下列何者呈現出的子路形象與上述造型相符", "opts": [["A", "季路問事鬼神。子曰：「未能事人，焉能事鬼？」"], ["B", "由也為之，比及三年，可使有勇，且知方也"], ["C", "為國以禮，其言不讓，是故哂之"], ["D", "發憤忘食，樂以忘憂，不知老之將至云爾"]], "exp": "題幹強調子路好強鬥勇之事，選項(B)呼應題幹內容。(A)向孔子請教有關如何祭祀鬼神。(C)論述子路說話不謙讓之事。(D)孔子教導子路為學心態。", "trans": "《史記．仲尼弟子列傳》：子路生性粗鄙，好逞強鬥勇，剛強直率，戴著公雞、雄豬的飾物。〈集解〉：雞和豬這兩種動物都象徵勇猛，子路喜歡逞強好勇，所以他才佩戴公雞、雄豬飾品來彰顯自己的勇氣。(A)子路向孔子請教有關如何祭祀鬼神的事，孔子說：「現在你們連人的事都沒做好，怎麼能夠做好有關『鬼』的事呢？」《論語．先進》。(B)讓我來治理，等到三年後，可使人民有勇氣，並且懂得禮義。(C)治國應當講禮，子路的話毫不謙讓，所以我笑他。(D)做學問時若覺有所不足便努力去做，連飯都忘了吃；讀書有心得時，便快樂得把一切憂愁都忘了，連自己快老了都不知道，如此而已！《論語．述而》。", "psg": "", "need_img": false, "imgs": [["", "img/侍坐/0aaa67b2e3d0fc7c.png"]], "per": {"A": "向孔子請教有關如何祭祀鬼神。", "C": "論述子路說話不謙讓之事。", "D": "孔子教導子路為學心態。", "B": "題幹強調子路好強鬥勇之事，選項(B)呼應題幹內容。"}}, {"n": 17, "ans": "B", "stem": "關於孔子「笑」的捕捉，《論語．陽貨》有另一則短文：「子之武城，聞弦歌之聲。夫子莞爾而笑，曰：『割雞焉用牛刀？』子游對曰：『昔者偃也聞諸夫子曰：君子學道則愛人，小人學道則易使也。』子曰：『二三子！偃之言是也。前言戲之耳。』」下列敘述何者正確", "opts": [["A", "孔子莞爾而笑的原因是因為看到此地有人用牛刀在殺雞"], ["B", "孔子莞爾而笑的原因是學生有把自己教導的治國方針用在小地區"], ["C", "孔子對自己不得體的笑話向子游道歉"], ["D", "孔子對自己不憐憫殺生的行為向學生道歉"]], "exp": "(A)(D)無此殺生的說法，孔子僅以殺雞用以譬喻治理武城，而牛刀是譬喻禮樂是用來治國的大方向。(C)孔子未向子游道歉，也無其必要，因為孔子是把對學生將自己所教導的禮樂治國之策付諸實踐的詼諧笑語，轉為認真的告訴其他學生。", "trans": "題幹語譯：孔子到武城，聽到了彈琴唱歌的聲音。孔子微笑的說：「殺雞哪裡需要用到牛刀呢？」子游回答道：「從前，我聽老師說過：『為政者學了禮樂就能體恤人民，平民百姓學了禮樂，就容易遵從政令。』」孔子說：「弟子們！言偃（子游）的話很對；我剛才的話是和他開玩笑的啊！」", "psg": "", "need_img": false, "per": {"A": "無此殺生的說法，孔子僅以殺雞用以譬喻治理武城，而牛刀是譬喻禮樂是用來治國的大方向。", "D": "無此殺生的說法，孔子僅以殺雞用以譬喻治理武城，而牛刀是譬喻禮樂是用來治國的大方向。", "C": "孔子未向子游道歉，也無其必要，因為孔子是把對學生將自己所教導的禮樂治國之策付諸實踐的詼諧笑語，轉為認真的告訴其他學生。"}}, {"n": 18, "ans": "C", "stem": "顏回為感念師恩將贈送紀念品給孔子，下列題辭何者最適合寫在紀念品上", "opts": [["A", "德業長昭／名山事業"], ["B", "功著杏林／杏林春暖"], ["C", "春風夏雨／桃李芬芳"], ["D", "螽斯衍慶／詩詠關睢"]], "exp": "(A)「德業長昭」哀輓男喪辭／「名山事業」用於祝賀人書局開業的賀辭。(B)由「杏林」可知詠醫界。(C)由「春風」、「桃李」可知。(D)賀結婚。", "trans": "", "psg": "", "need_img": false, "per": {"A": "「德業長昭」哀輓男喪辭／「名山事業」用於祝賀人書局開業的賀辭。", "B": "由「杏林」可知詠醫界。", "C": "由「春風」、「桃李」可知。", "D": "賀結婚。"}}, {"n": 19, "ans": "B", "stem": "關於《論語》一書，下列敘述何者正確", "opts": [["A", "始於〈學而〉，終於〈堯曰〉，篇名與內容關係密切"], ["B", "內容記錄孔子應答弟子及時人的談話，體裁為語錄體"], ["C", "文中有許多寓言，可看出孔子上課為引起學生學習動機的用心"], ["D", "南宋時，朱熹將《論語》與《孟子》、《荀子》、《中庸》合為「四書」"]], "exp": "(A)篇名與內容無關。(C)並無寓言。(D)《荀子》→《大學》。", "trans": "", "psg": "", "need_img": false, "per": {"A": "篇名與內容無關。", "C": "並無寓言。", "D": "《荀子》→《大學》。"}}, {"n": 20, "ans": "D", "stem": "下圖為孔子的個人 IG 帳號首頁，關於其個人檔案敘述，何者說明最適當？", "opts": [["A", "(甲)"], ["B", "(乙)"], ["C", "(丙)"], ["D", "(丁)"]], "exp": "(A)五十二歲擔任魯國大司寇，後因魯君荒於政事，孔子失望之餘，才帶領弟子周遊列國。(B)整理《詩》、《書》、《禮》、《樂》、《易》、《春秋》，非親自撰寫書籍。(C)春秋人。", "trans": "", "psg": "", "need_img": false, "imgs": [["", "img/侍坐/6bf7ab544d5dc2f7.png"]], "per": {"A": "五十二歲擔任魯國大司寇，後因魯君荒於政事，孔子失望之餘，才帶領弟子周遊列國。", "B": "整理《詩》、《書》、《禮》、《樂》、《易》、《春秋》，非親自撰寫書籍。", "C": "春秋人。"}}, {"n": 21, "ans": "A", "stem": "依據上文，孔子對顏回說：「使爾多財，吾為爾宰。」其中所包含的意義，下列何者<b>錯誤</b>", "opts": [["A", "希望顏回得志時別忘了自己"], ["B", "凸顯孔子對顏回人格氣度的肯定"], ["C", "讚嘆顏回與自己志同道合、理念一致"], ["D", "可看出孔子活潑幽默的一面"]], "exp": "此句話在肯定顏回，讚嘆顏回，並說明連自己都願意居顏回之下。言下之意，除了對顏回人格氣度的肯定外，也呈現出顏回與自己的理想一致，方能共事。而在被圍困的情況下，孔子還能講出這樣的話，足見其並非嚴肅的人，而是活潑幽默，充滿生氣的親切長者。", "trans": "題幹語譯：如果你有很多財富，我一定要當你的管家。", "psg": "　　孔子有江湖之氣，這與他的溫良恭儉讓，半點無有衝突；兩者并觀，互為一體，更顯其大。江湖，有活氣，水是通的，故孔子與各色人等，多有探問，皆可聞風相悅。江湖，有活氣，凡事新鮮，皆有興味。孔子的凡事有興味，連「鄙事」亦不例外，故他自言，「吾少也賤，故多能鄙事」，這貌似他老人家說話客氣，其實也是他掩不住的一分得意。不只年少，孔子及至年長，入了太廟，依然每事問。除了人事，孔子且連萬物，亦興味盎然，因此，他最博物，他還勸門人多讀《詩》，「小子！何莫學乎《詩》？」因為，「《詩》，可以興」，而且，可「多識於鳥、獸、草、木之名」。……<br><br>　　江湖風波險。孔子十幾年的行走列國，至少四次面臨生死關頭，命懸一線。頭一回匡地受圍。第二回桓魋追殺，弟子催他「可以速矣」，孔子則自壯膽氣地說道，「天生德於予，桓魋其如予何？」逃到鄭國，與門人失散；後來路人述他形狀，「纍纍若喪家之狗」，孔子聽聞，笑了起來。第三回遇難於蒲，蒲人要挾孔子不可前往衛國，雙方訂盟，蒲人才放孔子一行；結果，一出蒲地東門，孔子便頭也不回地，直往衛國疾奔而去。最後一次，就是那回絕糧於陳，眾弟子信心潰散，士氣渙然，唯有顏回不動如山，其靜似水，一邊勸慰，一邊辨析，孔子聽了開心，欣然笑曰，「使爾多財，吾為爾宰。」<br><br>　　後面的三次災厄，《史記》都明白交代了後續的發展，很清楚；唯獨頭一次的受困於匡，究竟孔子如何化解，讀了半天，仍覺得語焉不詳。《孔子家語》倒有個講法，最可見孔子江湖之氣，亦符合「興於《詩》」這樣的詩情，該書言道，「子路彈劍而歌，孔子和之，曲三終，匡人解圍。」如此死生之際，他們師徒彈劍而歌，一唱一和，論氣魄，論詩情，都讓千載後人忻然嚮往，也讓我們更能豁然，昔日孔子門庭是如何水深浪闊，又如何氣象萬千。<div class='aq-src'>（節錄自薛仁明〈彈劍而歌　孔子與江湖〉）</div>", "need_img": false, "per": {"A": "此句話在肯定顏回，讚嘆顏回，並說明連自己都願意居顏回之下。言下之意，除了對顏回人格氣度的肯定外，也呈現出顏回與自己的理想一致，方能共事。而在被圍困的情況下，孔子還能講出這樣的話，足見其並非嚴肅的人，而是活潑幽默，充滿生氣的親切長者。"}}, {"n": 22, "ans": "C", "stem": "依據上文，下列敘述何者正確", "opts": [["A", "作者認為孔子具有江湖之氣，與一般人對他溫良恭儉讓的形象有所矛盾"], ["B", "孔子周遊列國，四次面臨生死關頭，最後都是由顏回解圍"], ["C", "作者認為受困於匡的孔子師生，居然能彈劍而歌，可知其氣魄詩情"], ["D", "孔子勸門人多讀《易經》，方能領略深奧的天人之道"]], "exp": "(A)作者認為兩者不衝突。(B)未提及是誰解圍。(D)勸門人多讀《詩經》，因為不但可以興發志氣，還可以多認識鳥獸草木。", "trans": "", "psg": "　　孔子有江湖之氣，這與他的溫良恭儉讓，半點無有衝突；兩者并觀，互為一體，更顯其大。江湖，有活氣，水是通的，故孔子與各色人等，多有探問，皆可聞風相悅。江湖，有活氣，凡事新鮮，皆有興味。孔子的凡事有興味，連「鄙事」亦不例外，故他自言，「吾少也賤，故多能鄙事」，這貌似他老人家說話客氣，其實也是他掩不住的一分得意。不只年少，孔子及至年長，入了太廟，依然每事問。除了人事，孔子且連萬物，亦興味盎然，因此，他最博物，他還勸門人多讀《詩》，「小子！何莫學乎《詩》？」因為，「《詩》，可以興」，而且，可「多識於鳥、獸、草、木之名」。……<br><br>　　江湖風波險。孔子十幾年的行走列國，至少四次面臨生死關頭，命懸一線。頭一回匡地受圍。第二回桓魋追殺，弟子催他「可以速矣」，孔子則自壯膽氣地說道，「天生德於予，桓魋其如予何？」逃到鄭國，與門人失散；後來路人述他形狀，「纍纍若喪家之狗」，孔子聽聞，笑了起來。第三回遇難於蒲，蒲人要挾孔子不可前往衛國，雙方訂盟，蒲人才放孔子一行；結果，一出蒲地東門，孔子便頭也不回地，直往衛國疾奔而去。最後一次，就是那回絕糧於陳，眾弟子信心潰散，士氣渙然，唯有顏回不動如山，其靜似水，一邊勸慰，一邊辨析，孔子聽了開心，欣然笑曰，「使爾多財，吾為爾宰。」<br><br>　　後面的三次災厄，《史記》都明白交代了後續的發展，很清楚；唯獨頭一次的受困於匡，究竟孔子如何化解，讀了半天，仍覺得語焉不詳。《孔子家語》倒有個講法，最可見孔子江湖之氣，亦符合「興於《詩》」這樣的詩情，該書言道，「子路彈劍而歌，孔子和之，曲三終，匡人解圍。」如此死生之際，他們師徒彈劍而歌，一唱一和，論氣魄，論詩情，都讓千載後人忻然嚮往，也讓我們更能豁然，昔日孔子門庭是如何水深浪闊，又如何氣象萬千。<div class='aq-src'>（節錄自薛仁明〈彈劍而歌　孔子與江湖〉）</div>", "need_img": false, "per": {"A": "作者認為兩者不衝突。", "B": "未提及是誰解圍。", "D": "勸門人多讀《詩經》，因為不但可以興發志氣，還可以多認識鳥獸草木。"}}, {"n": 23, "ans": "D", "stem": "依據上文，作者認為孔子具有江湖之氣，是因為", "opts": [["A", "孔子富正義感，愛打抱不平，如同江湖俠士有著熱血心腸"], ["B", "孔子出身貧寒，地位卑微，較能了解下層社會的生活樣貌"], ["C", "孔子嚮往無憂無慮、與世無爭的江湖生活"], ["D", "孔子對萬事萬物興味盎然，且面對生命充滿活力和豁達的器量"]], "exp": "", "trans": "", "psg": "　　孔子有江湖之氣，這與他的溫良恭儉讓，半點無有衝突；兩者并觀，互為一體，更顯其大。江湖，有活氣，水是通的，故孔子與各色人等，多有探問，皆可聞風相悅。江湖，有活氣，凡事新鮮，皆有興味。孔子的凡事有興味，連「鄙事」亦不例外，故他自言，「吾少也賤，故多能鄙事」，這貌似他老人家說話客氣，其實也是他掩不住的一分得意。不只年少，孔子及至年長，入了太廟，依然每事問。除了人事，孔子且連萬物，亦興味盎然，因此，他最博物，他還勸門人多讀《詩》，「小子！何莫學乎《詩》？」因為，「《詩》，可以興」，而且，可「多識於鳥、獸、草、木之名」。……<br><br>　　江湖風波險。孔子十幾年的行走列國，至少四次面臨生死關頭，命懸一線。頭一回匡地受圍。第二回桓魋追殺，弟子催他「可以速矣」，孔子則自壯膽氣地說道，「天生德於予，桓魋其如予何？」逃到鄭國，與門人失散；後來路人述他形狀，「纍纍若喪家之狗」，孔子聽聞，笑了起來。第三回遇難於蒲，蒲人要挾孔子不可前往衛國，雙方訂盟，蒲人才放孔子一行；結果，一出蒲地東門，孔子便頭也不回地，直往衛國疾奔而去。最後一次，就是那回絕糧於陳，眾弟子信心潰散，士氣渙然，唯有顏回不動如山，其靜似水，一邊勸慰，一邊辨析，孔子聽了開心，欣然笑曰，「使爾多財，吾為爾宰。」<br><br>　　後面的三次災厄，《史記》都明白交代了後續的發展，很清楚；唯獨頭一次的受困於匡，究竟孔子如何化解，讀了半天，仍覺得語焉不詳。《孔子家語》倒有個講法，最可見孔子江湖之氣，亦符合「興於《詩》」這樣的詩情，該書言道，「子路彈劍而歌，孔子和之，曲三終，匡人解圍。」如此死生之際，他們師徒彈劍而歌，一唱一和，論氣魄，論詩情，都讓千載後人忻然嚮往，也讓我們更能豁然，昔日孔子門庭是如何水深浪闊，又如何氣象萬千。<div class='aq-src'>（節錄自薛仁明〈彈劍而歌　孔子與江湖〉）</div>", "need_img": false, "appraise": "本文敘述孔子深具江湖之氣，而這股江湖之氣表現在孔子對萬事萬物的高昂興致，以及面對人生困境時，毫無畏懼，甚至從容以對。文章所展現出來的孔子面貌，讓我們與他的距離不再遙遠。孔子，其實是很接近一般人的，他有幽默、有調皮、有豁達，是活生生的人；他氣魄，他詩情，他水深浪闊，他氣象萬千。", "per": {}}, {"n": 24, "ans": "D", "stem": "依據(甲)文，若要按照孔子學生的性格及專長，指派他們擔任國家內閣職務，下列哪一項內閣指派<b>最不適當</b>", "opts": [["A", "公西赤：外交部長"], ["B", "子路：國防部長"], ["C", "冉求：經濟部長"], ["D", "曾皙：教育部長"]], "exp": "(D)曾皙志在隱逸非治世，不強求為官。", "trans": "(甲)子路不加思索的搶先答道：「一個擁有一千輛兵車的國家，夾處在大國的中間，又受到外敵的侵略，接著又鬧饑荒，讓我來治理，等到三年後，可使人民有勇氣，並且懂得禮義。」孔子微微一笑。<br>「求！你怎樣呢？」冉有回答：「一個土地面積六、七十里見方或五、六十里見方的小國家，讓我來治理，等到三年後，可以使人民富足。至於禮樂教化，就只有等待更有才德的君子了。」<br>「赤！你怎樣呢？」公西華回答：「不敢說能做好，只是希望能有學習的機會。在諸侯祭祀或朝覲、會盟的典禮上，我願意穿著禮服，戴著禮帽，做個贊禮的小相。」<br>「點！你怎樣呢？」……曾皙說：「晚春時節，穿上做好的春裝，與五、六個成年人，還有六、七個孩童，到沂水邊洗洗澡，在求雨的祭壇上吹風乘涼，然後唱著歌回家。」孔子嘆息說：「我贊同點所說的呀！」", "psg": "(甲)　子路率爾而對曰：「千乘之國，攝乎大國之間，加之以師旅，因之以饑饉。由也為之，比及三年，可使有勇，且知方也。」夫子哂之。<br>　　「求，爾何如？」對曰：「方六、七十，如五、六十，求也為之，比及三年，可使足民。如其禮樂，以俟君子。」<br>　　「赤，爾何如？」對曰：「非曰能之，願學焉。宗廟之事，如會同，端章甫，願為小相焉。」<br>　　「點，爾何如？」……曰：「莫春者，春服既成，冠者五、六人，童子六、七人，浴乎沂，風乎舞雩，詠而歸。」夫子喟然嘆曰：「吾與點也！」<br><br>(乙)", "need_img": false, "imgs": [["", "img/侍坐/b90779a98812da1f.png"]], "per": {"D": "曾皙志在隱逸非治世，不強求為官。"}}, {"n": 25, "ans": "B", "stem": "依據(乙)圖，與 2021 年相比，臺灣在 2022 年 IMD 世界競爭力年報中總體排名進步了一名，臺灣在哪個領域表現進步", "opts": [["A", "政府效能與基礎建設"], ["B", "企業效能與基礎建設"], ["C", "企業效能與經濟表現"], ["D", "政府效能與經濟表現"]], "exp": "(B)由(乙)圖得知，企業效能與基礎建設分別升至第 6 名與第 13 名。", "trans": "(甲)子路不加思索的搶先答道：「一個擁有一千輛兵車的國家，夾處在大國的中間，又受到外敵的侵略，接著又鬧饑荒，讓我來治理，等到三年後，可使人民有勇氣，並且懂得禮義。」孔子微微一笑。<br>「求！你怎樣呢？」冉有回答：「一個土地面積六、七十里見方或五、六十里見方的小國家，讓我來治理，等到三年後，可以使人民富足。至於禮樂教化，就只有等待更有才德的君子了。」<br>「赤！你怎樣呢？」公西華回答：「不敢說能做好，只是希望能有學習的機會。在諸侯祭祀或朝覲、會盟的典禮上，我願意穿著禮服，戴著禮帽，做個贊禮的小相。」<br>「點！你怎樣呢？」……曾皙說：「晚春時節，穿上做好的春裝，與五、六個成年人，還有六、七個孩童，到沂水邊洗洗澡，在求雨的祭壇上吹風乘涼，然後唱著歌回家。」孔子嘆息說：「我贊同點所說的呀！」", "psg": "(甲)　子路率爾而對曰：「千乘之國，攝乎大國之間，加之以師旅，因之以饑饉。由也為之，比及三年，可使有勇，且知方也。」夫子哂之。<br>　　「求，爾何如？」對曰：「方六、七十，如五、六十，求也為之，比及三年，可使足民。如其禮樂，以俟君子。」<br>　　「赤，爾何如？」對曰：「非曰能之，願學焉。宗廟之事，如會同，端章甫，願為小相焉。」<br>　　「點，爾何如？」……曰：「莫春者，春服既成，冠者五、六人，童子六、七人，浴乎沂，風乎舞雩，詠而歸。」夫子喟然嘆曰：「吾與點也！」<br><br>(乙)", "need_img": false, "imgs": [["", "img/侍坐/b90779a98812da1f.png"]], "per": {"B": "由(乙)圖得知，企業效能與基礎建設分別升至第 6 名與第 13 名。"}}, {"n": 26, "ans": "B", "stem": "閱讀(甲)(乙)二圖文後，班上同學進行孔子弟子人物個性的問題討論，下列說法何者最適當？", "opts": [["A", "①、②皆正確"], ["B", "①正確，②無法判斷"], ["C", "①錯誤，②無法判斷"], ["D", "①無法判斷，②錯誤"]], "exp": "(B)由①「由也為之，比及三年，可使有勇，且知方也」可知正確。②由「宗廟之事，如會同，端章甫，願為小相焉」可知公西赤專長為祭祀或諸侯朝覲，但無法判斷是否能勝任「基礎建設」。", "trans": "(甲)子路不加思索的搶先答道：「一個擁有一千輛兵車的國家，夾處在大國的中間，又受到外敵的侵略，接著又鬧饑荒，讓我來治理，等到三年後，可使人民有勇氣，並且懂得禮義。」孔子微微一笑。<br>「求！你怎樣呢？」冉有回答：「一個土地面積六、七十里見方或五、六十里見方的小國家，讓我來治理，等到三年後，可以使人民富足。至於禮樂教化，就只有等待更有才德的君子了。」<br>「赤！你怎樣呢？」公西華回答：「不敢說能做好，只是希望能有學習的機會。在諸侯祭祀或朝覲、會盟的典禮上，我願意穿著禮服，戴著禮帽，做個贊禮的小相。」<br>「點！你怎樣呢？」……曾皙說：「晚春時節，穿上做好的春裝，與五、六個成年人，還有六、七個孩童，到沂水邊洗洗澡，在求雨的祭壇上吹風乘涼，然後唱著歌回家。」孔子嘆息說：「我贊同點所說的呀！」", "psg": "(甲)　子路率爾而對曰：「千乘之國，攝乎大國之間，加之以師旅，因之以饑饉。由也為之，比及三年，可使有勇，且知方也。」夫子哂之。<br>　　「求，爾何如？」對曰：「方六、七十，如五、六十，求也為之，比及三年，可使足民。如其禮樂，以俟君子。」<br>　　「赤，爾何如？」對曰：「非曰能之，願學焉。宗廟之事，如會同，端章甫，願為小相焉。」<br>　　「點，爾何如？」……曰：「莫春者，春服既成，冠者五、六人，童子六、七人，浴乎沂，風乎舞雩，詠而歸。」夫子喟然嘆曰：「吾與點也！」<br><br>(乙)", "need_img": false, "imgs": [["", "img/侍坐/b90779a98812da1f.png"]], "extra": "<div class='aq-sub'>① 子路個性較為積極上進，2023 年適合帶領臺灣提升總體競爭力排名。<br>② 公西赤的人生的目標是擔任「小相」，擔任臺灣政務官能讓「基礎建設」指標穩健的發展。</div>", "per": {"B": "由①「由也為之，比及三年，可使有勇，且知方也」可知正確。②由「宗廟之事，如會同，端章甫，願為小相焉」可知公西赤專長為祭祀或諸侯朝覲，但無法判斷是否能勝任「基礎建設」。"}}], "basicQ": [{"n": 1, "q": "下列各組「　」內的字，何者讀音相同？", "ans": "B", "opts": [["A", "千「乘」之國／「乘」風破浪", "ㄕㄥˋ／ㄔㄥˊ。"], ["B", "「比」及三年／「比」肩接踵", "皆ㄅㄧˋ。比肩接踵：形容人很多或接連不斷。"], ["C", "「舍」瑟而作／退避三「舍」", "ㄕㄜˇ／ㄕㄜˋ。退避三舍：比喻遇到實力很強的對手，為避免正面衝突折損太多，乃主動讓步，不與人爭。"], ["D", "「莫」春三月／「莫」名其妙", "ㄇㄨˋ／ㄇㄛˋ。"]]}, {"n": 2, "q": "下列文句，何者用字完全正確？", "ans": "B", "opts": [["A", "為一舉破獲犯罪集團，警方侍機而動", "侍→伺。"], ["B", "謹奉上家鄉土產鳳梨一箱，敬請哂納", ""], ["C", "表達意見應力求合乎邏輯，條理清皙", "皙→晰。"], ["D", "想到鉅額的投資虧損，不禁潰然而嘆", "潰→喟。"]]}, {"n": 3, "q": "下列各組「　」內的字，何者意義相同？", "ans": "C", "opts": [["A", "「以」吾一日長乎爾，毋吾以也／如或知爾，則何「以」哉", "因為／用。"], ["B", "子路率「爾」而對曰／求，「爾」何如", "語尾助詞，……的樣子／你。"], ["C", "方六、七十，「如」五、六十／宗廟之事，「如」會同，端章甫，願為小相焉", "皆為「或者」。"], ["D", "夫子喟然嘆曰：吾「與」點也／唯求則非邦也「與」", "贊同、讚許／通「歟」。"]]}, {"n": 4, "q": "〈子路曾皙冉有公西華侍坐〉一文中，子路言志，期許使人民「比及三年，可使有勇，且知方也」，孔子哂之的原因為何？", "ans": "D", "opts": [["A", "肯定子路果決明快，勇於承擔", ""], ["B", "鄙夷子路曠廢時日，有勇無謀", ""], ["C", "質疑子路好大喜功，短視近利", ""], ["D", "期許子路治國處世，謙讓為要", ""]]}, {"n": 5, "q": "下列「　」內的文句說明，何者與原意相同？", "ans": "C", "opts": [["A", "以吾一日長乎爾，「毋吾以也」：吾毋以也", "毋以吾也。"], ["B", "居則曰：「不吾知也」：吾不知也", "不知吾也。"], ["C", "如或知爾，「則何以哉」：則以何哉", ""], ["D", "對曰：「異乎三子者之撰」：三子者之撰異乎", "我和前三者所陳述的不同／前三者所陳述的各不相同。"]]}, {"n": 6, "q": "公西華回答孔子：「如會同，端章甫，願為小相焉。」「小」為謙詞。下列文句「　」內的字詞，何者用法與此<b>不相同</b>？", "ans": "B", "opts": [["A", "「拙作」最近問世，歡迎各位批評指教", ""], ["B", "「足下」深情厚誼，來日必定當面致謝", "乃古代下對上或同輩相稱的敬辭。"], ["C", "這學期「忝任」籃球隊長，請大家多多支持", ""], ["D", "看在我的「薄面」上，這次就請高抬貴手吧", ""]]}, {"n": 7, "q": "下列〈子路曾皙冉有公西華侍坐〉一文的文句，何者<b>不帶有</b>激問反詰的語氣？", "ans": "A", "opts": [["A", "夫三子者之言何如", "疑問語氣。"], ["B", "安見方六、七十，如五、六十，而非邦也者", ""], ["C", "宗廟會同，非諸侯而何", ""], ["D", "赤也為之小，孰能為之大", ""]]}, {"n": 8, "q": "下列有關《論語》的分析，何者正確？", "ans": "C", "opts": [["A", "編者：為孔子及其弟子、再傳弟子合編，非一人一時一地之作", "《論語》的編者是孔子的弟子與再傳弟子，孔子自身並未參與編輯。"], ["B", "篇章：共十篇，始於〈述而〉，終於〈堯曰〉，從篇名可大致了解文章內容", "《論語》共二十篇，始於〈學而〉，終於〈堯曰〉，其篇章乃是取為首的二、三字為名，與內容無關。"], ["C", "內容：以「仁」為中心，「忠、恕」為行仁的方法，治國重視「禮樂教化」", ""], ["D", "地位：為「語錄體之祖」，南宋朱熹將其列入十三經，成為科舉必考的經典", "南宋朱熹將《論語》列入「四書」。"]]}, {"n": 9, "q": "閱讀下文，依據上文，□□應填入：<div class='aq-sub'>　　這十四年，是他從五十五歲到六十八歲。這個年齡，即便放在普遍壽命大大延長的今天，也不適合流浪在外了。而□□，這麼一位大學者，卻把垂暮晚年付之於無休無止的漫漫長途，實在讓人震撼。<br>　　更讓人震撼的是，這十四年，他遇到的，有冷眼，有嘲諷，有搖頭，有威脅，有推拒，有轟逐，卻一點兒也沒有讓他猶豫停步。<br>　　他不是無處停步。任何地方都願意一個光有名聲和學問，卻沒有政治主張的他。任何地方都願意贍養他、供奉他、崇拜他，只要他只是一個話語不多的偶像。但是，他絕不願意這樣。<div class='aq-src'>（余秋雨《新文化苦旅．古道西風》）</div></div>", "ans": "B", "opts": [["A", "老子", ""], ["B", "孔子", "老子、莊子未曾為推廣治國理念而周遊各國，流浪在外。由文中「從五十五歲到六十八歲……流浪在外」正是孔子去魯適衛、周遊列國、陳蔡絕糧的時期，由此判斷為孔子而非墨子。"], ["C", "莊子", ""], ["D", "墨子", ""]]}, {"n": 10, "q": "承上文，「這十四年，他遇到的，有冷眼，有嘲諷，有搖頭，有威脅，有推拒，有轟逐，卻一點兒也沒有讓他猶豫停步。」下列何者最能說明這種精神？<div class='aq-sub'>　　這十四年，是他從五十五歲到六十八歲。這個年齡，即便放在普遍壽命大大延長的今天，也不適合流浪在外了。而□□，這麼一位大學者，卻把垂暮晚年付之於無休無止的漫漫長途，實在讓人震撼。<br>　　更讓人震撼的是，這十四年，他遇到的，有冷眼，有嘲諷，有搖頭，有威脅，有推拒，有轟逐，卻一點兒也沒有讓他猶豫停步。<br>　　他不是無處停步。任何地方都願意一個光有名聲和學問，卻沒有政治主張的他。任何地方都願意贍養他、供奉他、崇拜他，只要他只是一個話語不多的偶像。但是，他絕不願意這樣。<div class='aq-src'>（余秋雨《新文化苦旅．古道西風》）</div></div>", "ans": "C", "opts": [["A", "發憤忘食，樂以忘憂", "做學問發憤起來，連飯都忘了吃；有心得時，快樂得連憂愁都忘了。《論語．述而》。"], ["B", "知之為知之，不知為不知", "知道的就說知道，不知道的就說不知道。《論語．為政》。"], ["C", "義之所在，擇善固執", "只要是符合「義」的，便選擇好的、正確的事去做，且堅持不變。"], ["D", "君子求諸己，小人求諸人", "君子常責求自己，小人卻責求別人。《論語．衛靈公》。"]]}], "advQ": [{"kind": "table", "head": "二、進階練習", "cols": ["", "答案", "參考選項說明"], "rows": [["1", "<span class='wk-a'>B</span>", "(B)載歌載舞：邊唱歌，邊跳舞。形容盡情歡樂。"], ["2", "<span class='wk-a'>F</span>", "(F)縱然：即使。"], ["3", "<span class='wk-a'>E</span>", "(E)枉然：徒然。指毫無收穫。"], ["4", "<span class='wk-a'>G</span>", "(G)愕然：驚奇的樣子。"], ["5", "<span class='wk-a'>D</span>", "(D)學而不思"], ["6", "<span class='wk-a'>A</span>", "(A)牽強附會：硬把不相干的事物湊合在一起，勉強比附。"], ["7", "<span class='wk-a'>H</span>", "(H)啞然：笑聲。有時亦作一時說不出話來的樣子。"]], "note": "閱讀下文後，請從參考選項選擇適當的字詞，依序將代號填入（　）中。<br>參考選項：(A)牽強附會　(B)載歌載舞　(C)一語成讖　(D)學而不思　(E)枉然　(F)縱然　(G)愕然　(H)啞然<div class='aq-sub'>　　見那書生全不理睬，不由得暗暗發愁，再聽他所讀的原來是一部最平常不過的論語，只聽他讀道：「莫春者，春服既成，冠者五六人，童子六七人，浴乎沂，風乎舞雩，詠而歸。」讀得興高采烈，一誦三嘆，確似在春風中（1　），喜樂無已。黃蓉心道：「要他開口，只有出言相激。」當下冷笑一聲，說道：「論語（2　）讀了千遍，不明夫子微言大義，也是（3　）。」那書生（4　）止讀，抬起頭來，說道：「什麼微言大義，倒要請教。」黃蓉打量那書生，見他四十來歲年紀，頭戴逍遙巾，手揮摺疊扇，頦下一叢漆黑的長鬚，確是個飽學宿儒模樣，於是冷笑道：「閣下可知孔門弟子，共有幾人？」那書生笑道：「這有何難？孔門弟子三千，達者七十二人。」黃蓉問道：「七十二人中有老有少，你可知其中冠者幾人，少年幾人？」那書生愕然道：「論語中未曾說起，經傳中亦無記載。」黃蓉道：「我說你不明經書上的微言大義，豈難道說錯了？剛才我明明聽你讀道：冠者五六人，童子六七人。五六得三十，成年的是三十人，六七四十二，少年是四十二人。兩者相加，不多不少是七十二人。瞧你這般（5　），嘿！殆哉，殆哉！」那書生聽她這般（6　）的胡解經書，不禁（7　）失笑，可是心中也暗服她的聰明機智。<div class='aq-src'>（金庸《射鵰英雄傳》）</div></div>"}], "handoutV2": [{"title": "一、作者與題解", "page": "", "blocks": [["text", "mj", "壹　課文重點整理"], ["table", "", [["萬世師表、至聖先師──孔子"], ["字號", "孔子名丘，字仲尼"], ["時代", "<span class=\"jy-cir\">①</span><span class=\"jy-blank\" onclick=\"this.classList.toggle(&#39;show&#39;)\"><span class=\"jy-blank-ph\">&nbsp;&nbsp;&nbsp;&nbsp;</span><span class=\"jy-blank-ans\">春秋</span></span>魯國　陬邑（今山東省　曲阜市）人"], ["生平<br>及<br>成就", "年少貧賤，濡染周禮<br>父親叔梁紇，母親顏徵在。孔子兒時玩遊戲常常擺設俎豆等祭器，模仿祭禮動作，深受周禮薰陶。十九歲結婚，生子孔鯉，為了謀生他先後做過「委吏」、「乘田」。成年後的孔子回憶這段生活時曾感嘆的說：「吾少也賤，故多能鄙事。」（論語　子罕）<br>好學善問，有教無類<br>孔子十五歲志於學，學習內容以詩、書、禮、樂為主，曾向郯子學官制，向老子問禮，向師襄學琴，向萇弘問古樂。孔子首開平民教育之風，主張「有教無類」，只要備「束脩（十條乾肉）」之禮，就可以跟隨他學習<br>去魯至齊，接淅去齊<br>孔子三十五歲時，季孫氏專政且僭越，魯國禮壞樂崩，孔子因此不願繼續待在魯國，便帶著弟子前往齊國，期望施展抱負。孟子　萬章下記載：「孔子之去齊，接淅而行（形容時間急迫，匆忙離去）。」（語譯：孔子在淘米做飯時倉皇離開齊國，拎起還沒來得及瀝乾的米便匆匆趕路。）<br>周遊列國，坎坷流轉<br>孔子周遊列國，欲推行仁政、德政的主張，懷抱著「知其不可為而為之」的理想，堅持一貫的理念。孔子歷盡艱辛，四處遊說，宣揚政治理想終未能實現<br>世衰道微，整理六經<br>孔子對「六經」的整理，無疑是他對中華文化最大的貢獻。司馬遷曰：「孔子擔憂王道廢弛、邪道興起，於是論定編次詩、書，修訂振興禮、樂。」（史記　儒林列傳）孟子則說：「世衰道微，邪說暴行有作。臣弒其君者有之，子弒其父者有之。孔子懼，作<span class=\"jy-cir\">②</span><span class=\"jy-blank\" onclick=\"this.classList.toggle(&#39;show&#39;)\"><span class=\"jy-blank-ph\">&nbsp;&nbsp;&nbsp;&nbsp;</span><span class=\"jy-blank-ans\">春秋</span></span>。」（孟子　滕文公下）（語譯：世道衰微，錯誤的學說與暴虐的行為又再度興起。臣子殺害國君的事發生了，兒子殺害父親的事也發生了。孔子非常害怕擔心，便整理了春秋這本史書。）"]]], ["table", "", [["其他", "至聖：<span class=\"jy-cir\">③</span><span class=\"jy-blank\" onclick=\"this.classList.toggle(&#39;show&#39;)\"><span class=\"jy-blank-ph\">&nbsp;&nbsp;&nbsp;&nbsp;</span><span class=\"jy-blank-ans\">孔子</span></span><br>亞聖：<span class=\"jy-cir\">④</span><span class=\"jy-blank\" onclick=\"this.classList.toggle(&#39;show&#39;)\"><span class=\"jy-blank-ph\">&nbsp;&nbsp;&nbsp;&nbsp;</span><span class=\"jy-blank-ans\">孟子</span></span>", "復聖：顏回<br>述聖：子思", "宗聖：曾參"]]], ["table", "", [["選錄<br>篇章", "本文選自論語 先進，原文無標題，標題乃編者所訂。論語各章多為簡要語錄，然而本章卻超過四百字，結構完整，人物形象鮮明，在論語中極為特出<br>全文記錄孔子與學生的日常對話。從孔子引導學生暢談志向，看出學生的政治抱負及人格特質。其中孔子對曾皙的讚許，更透露出儒家淑世的精神與期許世界大同的襟懷"]]]]}, {"title": "二、國學常識　(一)文體簡介——語錄體", "page": "", "blocks": [["text", "para", "1.體例：「語錄體」是指直接記錄或摘錄言論的一種文體。中國古代散文中，尚書主要是記言散文，至春秋　戰國，哲人學者或聚眾講學，或與時人辯論，由其弟子加以記錄，匯集成篇，遂成語錄體著作，論語尤為典範。"], ["text", "para", "2.影響：繼論語之後，孟子、墨子、莊子、荀子、韓非子亦偶見語錄。漢代　揚雄的法言、隋代　王通的中說，文字和體裁都有意模仿論語。論語語錄體對後世的影響，還及於世說新語之類的筆記小說。"], ["text", "para", "3.著作：「語錄」此名稱至唐代方才出現。唐代　孔思尚有宋齊語錄十卷，為「語錄」稱謂之始。唐代僧人講佛，弟子往往直錄其語，沿稱「語錄」。至於宋代理學家傳道講學，弟子加以記錄整理，亦成語錄書，如：程顥、程頤　二程粹言、朱熹　朱子語類。明代　王陽明　傳習錄亦採語錄體。"]]}, {"title": "(二)「論語」簡介", "page": "", "blocks": [["table", "", [["作者", "孔子弟子及再傳弟子"], ["文體", "記載孔子應答弟子及時人的對話，是一部<span class=\"jy-cir\">①</span><span class=\"jy-blank\" onclick=\"this.classList.toggle(&#39;show&#39;)\"><span class=\"jy-blank-ph\">&nbsp;&nbsp;&nbsp;&nbsp;</span><span class=\"jy-blank-ans\">語錄體</span></span>經典。"], ["篇章", "共二十篇，始於<span class=\"jy-cir\">②</span><span class=\"jy-blank\" onclick=\"this.classList.toggle(&#39;show&#39;)\"><span class=\"jy-blank-ph\">&nbsp;&nbsp;&nbsp;&nbsp;</span><span class=\"jy-blank-ans\">學而</span></span>，終於<span class=\"jy-cir\">③</span><span class=\"jy-blank\" onclick=\"this.classList.toggle(&#39;show&#39;)\"><span class=\"jy-blank-ph\">&nbsp;&nbsp;&nbsp;&nbsp;</span><span class=\"jy-blank-ans\">堯曰</span></span><br>前十篇稱為「上論」，後十篇稱為「下論」。每篇篇名，均各取首章首句去除「子曰」、「孔子」後之二、三字為篇名，篇名與篇中各則涵義不盡相關"], ["內容", "以<span class=\"jy-cir\">④</span><span class=\"jy-blank\" onclick=\"this.classList.toggle(&#39;show&#39;)\"><span class=\"jy-blank-ph\">&nbsp;&nbsp;&nbsp;&nbsp;</span><span class=\"jy-blank-ans\">仁</span></span>為中心，<span class=\"jy-cir\">⑤</span><span class=\"jy-blank\" onclick=\"this.classList.toggle(&#39;show&#39;)\"><span class=\"jy-blank-ph\">&nbsp;&nbsp;&nbsp;&nbsp;</span><span class=\"jy-blank-ans\">忠、恕</span></span>為行仁的方法"], ["備註", "南宋　朱熹將論語與<span class=\"jy-cir\">⑥</span><span class=\"jy-blank\" onclick=\"this.classList.toggle(&#39;show&#39;)\"><span class=\"jy-blank-ph\">&nbsp;&nbsp;&nbsp;&nbsp;</span><span class=\"jy-blank-ans\">孟子</span></span>、<span class=\"jy-cir\">⑦</span><span class=\"jy-blank\" onclick=\"this.classList.toggle(&#39;show&#39;)\"><span class=\"jy-blank-ph\">&nbsp;&nbsp;&nbsp;&nbsp;</span><span class=\"jy-blank-ans\">大學</span></span>、<span class=\"jy-cir\">⑧</span><span class=\"jy-blank\" onclick=\"this.classList.toggle(&#39;show&#39;)\"><span class=\"jy-blank-ph\">&nbsp;&nbsp;&nbsp;&nbsp;</span><span class=\"jy-blank-ans\">中庸</span></span>合為「四書」"]]]]}, {"title": "(三)孔門「四科十哲」", "page": "", "blocks": [["text", "para", "（論語　先進）子曰：「從我於陳、蔡者，皆不及門也。」德行：顏淵、閔子騫、冉伯牛、仲弓。言語：宰我、子貢。政事：冉有、季路。文學：子游、子夏。分述整理如下："], ["table", "", [["科別", "人名", "字號", "相關事蹟"], ["德行", "顏回", "子淵", "子曰：「賢哉回也！一簞食，一瓢飲，在陋巷。人不堪其憂，回也不改其樂。賢哉回也！」 （論語 雍也）<br>語譯：孔子說：「多麼賢良啊顏回！吃的是一小簍飯，喝的是一瓢湯水，住在陋巷裡。別人忍受不了這種貧苦，而顏回卻不改變他好學的樂趣。多麼賢良啊顏回！」<br>安貧樂道，「其心三月不違仁。」<br>語譯：他的內心長久不背離仁德。<br>不遷怒，不貳過。<br>語譯：不把憤怒移轉到無關的人身上，不犯同樣的過失。"], ["", "閔損", "子騫", "子曰：「孝哉閔子騫！人不間於其父母昆弟之言。」 （論語　先進）<br>語譯：孔子說：「真是孝順啊閔子騫！人們對他父母兄弟稱讚他孝順友愛的話，都沒有異議。」"], ["", "冉耕", "伯牛", "伯牛有疾，子問之，自牖執其手，曰：「亡之，命矣夫！斯人也而有斯疾也！斯人也而有斯疾也！」 （論語 雍也）<br>語譯：冉伯牛得了惡疾，孔子前往探視慰問，從窗戶外抓著他的手，說：「沒有得到這種病的道理，這是天命的關係啊！這樣有德行的人，卻得到這種病！這樣有德行的人，卻得到這種病呀！」"], ["", "冉雍", "仲弓", "出身微賤，勤奮向學。<br>子謂仲弓曰：「犁牛之子騂且角，雖欲勿用，山川其舍諸？」<br>（論語　雍也）<br>語譯：孔子談論到仲弓說：「一頭毛色駁雜的牛所生的小牛，毛色純赤且兩角端正，人們雖然不想用牠來作犧牲祭品，但是山川的神明哪裡會捨棄牠呢？」"], ["言語", "宰予", "子我", "宰予晝寢。子曰：「朽木不可雕也，糞土之牆不可杇也，於予與何誅！<br>（論語　公冶長）<br>語譯：宰予白天睡覺。孔子說：「腐朽的木頭不可以用來雕刻，用汙穢的泥土築成的牆無法加以粉刷，對於宰予這樣的人，我還有什麼好責備的！」"], ["", "端木賜", "子貢", "曾仕於衛、魯，游說於齊、吳等國，聞名諸侯，經商於曹、魯之間。<br>賜不受命，而貨殖焉，億則屢中。 （論語 先進）<br>語譯：子貢不相信命運，經商致富，臆測常常猜中。"]]], ["table", "", [["政事", "冉求", "子有", "個性謙退，孔子曾說：「求也退，故進之。」<br>語譯：冉求為人退縮，所以鼓勵他進取。<br>曾為季氏宰，為季氏聚斂，孔子斥責曰：「非吾徒也。小子鳴鼓而攻之，可也。」 （論語 先進）<br>語譯：冉求不是我的門徒。弟子們鳴鼓來聲討他，是可以的。"], ["", "仲由", "子路（季路）", "為人直率魯莽，好勇力。<br>子曰：「道不行，乘桴浮於海，從我者其由與。」子路聞之喜。子曰：「由也，好勇過我，無所取材。」 （論語 公冶長）<br>語譯：孔子說：「我的理想不能實行，不如乘著木筏漂流到海外去，能夠跟隨我的大概只有仲由吧。」子路聽了很高興。孔子就說：「仲由啊，你比我還勇敢，但我還沒找到製作木筏的材料。」"], ["文學", "言偃", "子游", "子之武城，聞弦歌之聲。夫子莞爾而笑，曰：「割雞焉用牛刀？」子游對曰：「昔者偃也聞諸夫子曰：『君子學道則愛人，小人學道則易使也。』」 （論語　陽貨）<br>語譯：孔子到武城，聽見彈琴唱歌的聲音。孔子微笑，說：「殺雞哪裡要用到牛刀呢？」子游回答道：「從前我聽老師說過：『在上位的人學了禮樂就能體恤人民，平民百姓學了禮樂就容易遵從政令。』」"], ["", "卜商", "子夏", "子曰：「起予者商也！始可與言詩已矣。」 （論語 八佾）<br>語譯：啟發我的人是卜商呀！現在可以和他討論詩經了。"]]]]}, {"title": "三、課文深究　(一)文本透視鏡", "page": "", "blocks": [["table", "", [["寫作背景", "1.孔子曾擔任小官「委吏」與「乘田」，歷時不長。年過三十，即在家設教授徒。私學的創設，打破「學在官府」的傳統，進一步促進學術文化的下移<br>2.據錢穆所著孔子傳，推論此章應該發生在孔子五十歲出仕之前<br>3.孔門講學本在用世，子路長於治軍，冉有長於理財，公西華長於外交禮節，三人所學各有專長。孔子既寄慨於一生理想未能用世，又深惜三位弟子意於進取，卻擔心他們懷才不遇，於是特別激賞放情山水、從容自樂於日常的曾皙<br>4.就本章內容而言，師生討論、言志，當是在生活比較安穩的時期，錢穆將其置於「孔子第一期之教育生涯」"]]], ["table", "", [["結構", "段落", "旨意", "讀見真相"], ["起<br>孔子問志", "第一段", "孔子鼓勵各自言志", "師生相處氣象。凸顯孔子和藹可親，循循善誘的長者風範"], ["承<br>弟子述志", "第二段<br>～<br>第四段", "子路──率爾而對<br>（軍事、禮義）", "「千乘之國，攝乎大國之間，加之以師旅，因之以饑饉。由也為之，比及三年，可使有勇，且知方也」<br>→希望在治國上表現軍事才能，則顯現其自負。孔子「哂之」，褒貶寓含其中"], ["", "", "冉有──問而後答<br>（經濟、民生）", "「方六、七十，如五、六十，求也為之，比及三年，可使足民。如其禮樂，以俟君子」<br>→冉有表示須待更賢能的君子才能實行禮義教化。呈現冉有「退」與「讓」的個性"], ["", "", "公西華──問而後答<br>（外交）", "「非曰能之，願學焉。宗廟之事，如會同，端章甫，願為小相焉」<br>→願做祭典中的「小相」（典禮中擔任司儀或贊禮［輔佐禮儀進行］的人）"], ["轉<br>孔子讚許<br>曾皙之志", "第五段", "曾皙──止瑟而答<br>（禮樂融合）", "1.「莫春者，春服既成，冠者五、六人，童子六、七人，浴乎沂，風乎舞雩，詠而歸」<br>→曾皙所言乃儒家內聖外王事業完成之後，一種從容、祥和、寧靜的境界，因此深獲孔子嘉許。曾皙回溯生命的本源，呈現出人與人、人與自然和諧交融的感受<br>2.「夫子喟然嘆曰：『吾與點也！』」<br>→曾皙描繪的是在禮樂治理下的太平社會的縮影，與孔子「風清俗美、人民安樂」的政治理想正好相符"], ["合<br>孔子評志", "第六段", "強調<span class=\"jy-cir\">①</span><span class=\"jy-blank\" onclick=\"this.classList.toggle(&#39;show&#39;)\"><span class=\"jy-blank-ph\">&nbsp;&nbsp;&nbsp;&nbsp;</span><span class=\"jy-blank-ans\">禮讓</span></span>", "1.「三子者出，曾皙後。曾皙曰：『夫三子者之言何如？』子曰：『亦各言其志也已矣。』」<br>2.「曰：『夫子何哂由也？』曰：『為國以<span class=\"jy-cir\">②</span><span class=\"jy-blank\" onclick=\"this.classList.toggle(&#39;show&#39;)\"><span class=\"jy-blank-ph\">&nbsp;&nbsp;&nbsp;&nbsp;</span><span class=\"jy-blank-ans\">禮</span></span>，其言不讓，是故哂之。』」<br>3.「『唯求則非邦也與？』『安見方六、七十，如五、六十，而非邦也者？』」<br>4. 「『唯赤則非邦也與？』『宗廟會同，非諸侯而何？赤也為之小，孰能為之大？』」<br>→孔子認為子路言及以禮治國，自己卻毫不謙讓；冉有志向雖亦是治國大事，但其言謙讓；公西華亦然，且更謙虛。「宗廟會同」與「諸侯（之事）」皆同為政治，孔子肯定公西華的才能與謙遜。孔子的回答均針對「<span class=\"jy-cir\">③</span><span class=\"jy-blank\" onclick=\"this.classList.toggle(&#39;show&#39;)\"><span class=\"jy-blank-ph\">&nbsp;&nbsp;&nbsp;&nbsp;</span><span class=\"jy-blank-ans\">其言不讓</span></span>」，為「是故哂之」具體說明"]]]]}, {"title": "(二)文本異世界", "page": "", "blocks": [["table", "", [["主旨", "全文記錄孔子與學生的日常對話。「<span class=\"jy-cir\">①</span><span class=\"jy-blank\" onclick=\"this.classList.toggle(&#39;show&#39;)\"><span class=\"jy-blank-ph\">&nbsp;&nbsp;&nbsp;&nbsp;</span><span class=\"jy-blank-ans\">志</span></span>」是貫穿全文的核心，透過弟子「言志」來表現孔子「治國以<span class=\"jy-cir\">②</span><span class=\"jy-blank\" onclick=\"this.classList.toggle(&#39;show&#39;)\"><span class=\"jy-blank-ph\">&nbsp;&nbsp;&nbsp;&nbsp;</span><span class=\"jy-blank-ans\">禮</span></span>」的中心思想"], ["文體", "<span class=\"jy-cir\">③</span><span class=\"jy-blank\" onclick=\"this.classList.toggle(&#39;show&#39;)\"><span class=\"jy-blank-ph\">&nbsp;&nbsp;&nbsp;&nbsp;</span><span class=\"jy-blank-ans\">語錄</span></span>體"], ["寫作特色", "1.人物形象鮮明，栩栩如生：子路最先搶答，且說明志向時毫不謙讓，可知其急躁自負。冉有等待君子禮樂教化、公西華表明願為小相，都可看出他們謙恭謹慎的個性。而曾皙與眾不同的嚮往，點出其灑脫真誠<br>2.因材施教、啟發引導式教學：在孔子的鼓勵之下，學生各言其志，具體描繪心中藍圖，暢所欲言，透顯出師生之間和樂融融、無話不談的交流互動。夫子「哂由」，並讚嘆曾皙充滿詩意的理想境界，隱約可看出孔子對禮樂教化、太平盛世的期待<br>3.文章脈絡清晰，結構完整：本文是論語最長的篇章，記敘完整，涉及眾多人物，為孔門教學場景留下最精彩的一頁"]]]]}, {"title": "一、形近字", "page": "", "blocks": [["text", "mj", "貳　形音義比較"], ["table", "", [["形", "音", "義", "例"], ["撰", "ㄓㄨㄢˋ", "著述", "「撰」文、「撰」稿"], ["", "", "陳述", "異乎二三子之「撰」"], ["饌", "ㄓㄨㄢˋ", "吃喝", "有酒食，先生「饌」 （論語 為政）"], ["", "", "酒食菜餚", "肴「饌」"], ["巽", "ㄒㄩㄣˋ", "卑順、謙恭", "「巽」與之言 （論語 子罕）"], ["", "", "易經卦名", "「巽」卦"]]]]}, {"title": "二、一字多音", "page": "", "blocks": [["table", "", [["字", "音", "義", "例"], ["舍", "ㄕㄜˇ", "放下", "鼓瑟希，鏗爾，「舍」瑟而作"], ["", "", "止息、休息", "逝者如斯夫！不「舍」晝夜     （論語 子罕）"], ["", "ㄕㄜˋ", "量詞。古代計算行軍里數的單位。三十里為一舍", "退避三「舍」"], ["與", "ㄩˇ", "<span class=\"jy-cir\">①</span><span class=\"jy-blank\" onclick=\"this.classList.toggle(&#39;show&#39;)\"><span class=\"jy-blank-ph\">&nbsp;&nbsp;&nbsp;&nbsp;</span><span class=\"jy-blank-ans\">贊同、讚許</span></span>", "吾「與」點也"], ["", "", "支持、贊助", "天道無親，常「與」善人  （老子第七十九章）"], ["", "", "向、對", "「與」虎謀皮"], ["", "", "等待", "時不我「與」"], ["", "", "同類", "民胞物「與」"], ["", "<span class=\"jy-cir\">②</span><span class=\"jy-blank\" onclick=\"this.classList.toggle(&#39;show&#39;)\"><span class=\"jy-blank-ph\">&nbsp;&nbsp;&nbsp;&nbsp;</span><span class=\"jy-blank-ans\">ㄩˊ</span></span>", "通「歟」，句末助詞，表達疑問、反詰、感嘆的語氣", "唯赤則非邦也「與」"], ["", "<span class=\"jy-cir\">③</span><span class=\"jy-blank\" onclick=\"this.classList.toggle(&#39;show&#39;)\"><span class=\"jy-blank-ph\">&nbsp;&nbsp;&nbsp;&nbsp;</span><span class=\"jy-blank-ans\">ㄩˋ</span></span>", "參加", "參「與」"]]]]}, {"title": "倒裝", "page": "", "blocks": [["text", "mj", "參　修辭"], ["table", "", [["定義", "為了音律上的需要，或為引起讀者注意，強調某些語詞，刻意破壞句子原本順序，顛倒文法邏輯詞序的修辭法"], ["例句", "一日長乎爾→<span class=\"jy-cir\">①</span><span class=\"jy-blank\" onclick=\"this.classList.toggle(&#39;show&#39;)\"><span class=\"jy-blank-ph\">&nbsp;&nbsp;&nbsp;&nbsp;</span><span class=\"jy-blank-ans\">長乎爾一日</span></span><br>毋吾以也→<span class=\"jy-cir\">②</span><span class=\"jy-blank\" onclick=\"this.classList.toggle(&#39;show&#39;)\"><span class=\"jy-blank-ph\">&nbsp;&nbsp;&nbsp;&nbsp;</span><span class=\"jy-blank-ans\">毋以吾也</span></span><br>不吾知也→不知吾也<br>則何以哉→則以何哉<br>可使足民→<span class=\"jy-cir\">③</span><span class=\"jy-blank\" onclick=\"this.classList.toggle(&#39;show&#39;)\"><span class=\"jy-blank-ph\">&nbsp;&nbsp;&nbsp;&nbsp;</span><span class=\"jy-blank-ans\">可使民足</span></span>"]]]]}, {"title": "一、與孔子相關的對聯", "page": "", "blocks": [["text", "mj", "肆　延伸學習"], ["table", "", [["", "對聯", "出處"], ["1.", "德侔天地／道貫古今", "山東　曲阜　孔廟"], ["2.", "成春秋一書，褒貶嚴斧鉞／留洙泗片席，俎豆以馨香", "山東　曲阜　孔廟"], ["3.", "道若江河，隨地盡成洙泗／聖如日月，普天猶是春秋", "山東　樂陵　文廟"], ["4.", "觀於海者難為水／譬如天之不可階", "山西　平遙　文廟"], ["5.", "生民來，未有夫子也／知我者，其惟春秋乎", "山西　平遙　文廟"], ["6.", "道與天地參，功滿天地，名滿天地／書留春秋在，知我春秋，罪我春秋", "山西　平遙　文廟"]]]]}, {"title": "二、「論語」中的成語", "page": "", "blocks": [["table", "", [["成語", "釋義", "例句"], ["巧言令色", "形容花言巧語，虛偽討好。", "看他對總經理巧言令色的樣子，真是個討厭的傢伙。"], ["行不由徑", "走路不抄小路捷徑。比喻行事光明正大，不投機取巧。", "朱主任為人行不由徑，處事公正，受到同事的愛戴。"], ["文質彬彬", "原形容人既文雅又樸實，後形容人文雅有禮貌。", "這位主持人容貌出眾，談吐優雅，文質彬彬，吸引很多觀眾。"], ["風行草偃", "比喻在上位者以德化民。", "校長以身作則，實行「綠色生活」，於是風行草偃，全校師生一致努力踐行。"]]]]}, {"title": "三、相關作品欣賞", "page": "", "blocks": [["text", "para", "（一）十五志於學──也談「生涯規劃」                                              薛仁明"], ["text", "para", "志氣如詩。好的時代裡，年少之人，各有其志；而少年十五二十時，也人人皆可是詩人。詩主感，又主興；孔子說，「興於詩」。詩向來也講不明，說不清；現在學校教授古詩，為圖方便，硬是逐句翻譯成大白話：說是教學，其實是造孽。他們把學生僅剩的感悟能力，也將扼殺殆盡。"], ["text", "para", "詩，是透過文字，與天地精神相往來；詩，是通過文字，與人世風景相映照。詩是孔子說的「思無邪」，是日月光華照見天地萬物，歷然爽豁，俱生好意。詩是年少的志氣滿滿。          ；即便稍稍過當，即便恣縱無涯，都無礙於那厚實底氣。年少青春，有此深厚底氣，好比盤纏殷實，往後的人生，便可「走盡天涯，歌盡桃花」。"], ["text", "para", "「走盡天涯，歌盡桃花」，這般且吟且嘯、且歌且謠，完全迥異於今日所言的「生涯規劃」。「生涯規劃」之為惡，正在於完全沒有詩情。年少時代，無有詩情，何言青春？無有詩情，何言志氣？「生涯規劃」，是標準化社會的產物，明確清晰，像張工程圖；          ，成為一個標準產品。「生涯規劃」之人生，如生產線。此時此地，裝零件；彼時彼地，釘螺絲；傳送至末了，裝配完畢，但生命也成烏有。雖然即將烏有，這物化社會仍因利之所在，透過各種訊息，以不連累他人為名，勸你儘早再做個「規劃」，所謂「生前契約」。"], ["text", "para", "這條生產線上，人人依照相仿的「進度」，按部就班，循序漸進。通常，開頭是用功讀書，考好學校；不用功也行，總之找好工作，努力賺錢，設法理財；然後購車、買房、養保險，最後，再來個「生前契約」吧！如此這般，賺錢、退休、養老，如果人生只剩如此，真是不要也罷！休怪年輕人無感無興，也休怪年輕人不知志氣為何物。畢竟，除了這一份份的「生涯規劃」，我們成人世界，到底還能給她們什麼？又能教給他們什麼？"], ["text", "para", "孔子的時代，重重憂患；但他那時，滿滿志氣。          ，到了晚年，還動輒問對門人，「盍各言爾志？」千百年後，孔子若是地下有知，當仍願意召喚今日年少者：甩開那勞什子的「生涯規劃」吧！來吧！說說你的志向，老夫愛聽呢！"], ["text", "q", "【(C)】1.依據上文，下列何者符合作者對於「詩」的觀點？"], ["text", "opt", "(A)詩氣是文學的表現，與志向無關　　　(B)「興於詩」表示詩能夠撥亂興治"], ["text", "opt", "(C)詩化的語言，映照天地人世風景　　　(D)「思無邪」指詩使人易心生雜念"], ["text", "exp", "【解析】(A)由「志氣如詩」可知為非。(B)由「詩主感，又主興」可知作者主要強調詩要自己感悟，並未提及有撥亂興治的功能。撥亂興治：平定亂世，從事建設。(C)由「詩，是透過文字，與天地精神相往來；詩，是通過文字，與人世風景相映照」可知。(D)由「是日月光華照見天地萬物，歷然爽豁，俱生好意」可知為非。"], ["text", "q", "【(B)】2.若要將(甲)、(乙)、(丙)填入上文，使全文完整通順，則三處          內依序應填入："], ["text", "para", "(甲)他十五志於學，而後志於道"], ["text", "para", "(乙)青衿之志，貴在昂揚，貴在飽滿"], ["text", "para", "(丙)人但凡按部就班，就能達成「目的」"], ["text", "opt", "(A)(乙)(甲)(丙)　　　(B)(乙)(丙)(甲)　　　(C)(丙)(甲)(乙)　　　(D)(丙)(乙)(甲)"], ["text", "exp", "【解析】(B)由「詩是年少的志氣滿滿」、「即便稍稍過當，即便恣縱無涯」前後文意可知應接(乙)。而從「明確清晰，像張工程圖」、「成為一個標準產品」可知應接(丙)。又由「孔子的時代」、「但他那時，滿滿志氣」與「到了晚年，還動輒問對門人，『盍各言爾志？』」可知應接(甲)。"], ["text", "q", "【(D)】3.依據上文，下列敘述何者正確？"], ["text", "opt", "(A)作者認為年輕人要遵循常規擬定生涯規劃，完成目標"], ["text", "opt", "(B)作者提倡「生前契約」的觀念，可以保障人生的幸福"], ["text", "opt", "(C)「走盡天涯，歌盡桃花」就是如生產線的「生涯規劃」人生"], ["text", "opt", "(D)作者鼓勵年輕人要拋開制式觀念，胸懷詩情，才能懷抱壯志"], ["text", "exp", "【解析】(A)作者認為遵循常規的生涯規劃，賺錢、退休、養老，如果人生只剩如此，真是不要也罷。(B)由「這物化社會仍因利之所在，透過各種訊息，以不連累他人為名，勸你儘早再做個『規劃』，所謂『生前契約』」，可知作者未提倡「生前契約」的觀念。(C)「走盡天涯，歌盡桃花」是充滿詩情、詩志的人生。(D)由「千百年後，孔子若是地下有知，當仍願意召喚今日年少者：甩開那勞什子的『生涯規劃』吧！來吧！說說你的志向，老夫愛聽呢！」可知。"], ["text", "para", "【賞析】本文作者旨在論述詩言志，孔子曾說：「詩可以興。」由於「詩」乃出自於人的感情，這種感情的語言在反覆的抑揚吟詠之間，可進入人的內心深處，興發鼓舞人意志的作用。而詩也是孔子所說的「思無邪」，能讓人心無邪念、純正而合乎禮教。作者對於現今社會過於強調標準化的「生涯規劃」，提出獨特的看法，作者認為年輕人應拋開這種制式的觀念，要胸有詩情，才能懷抱壯志。"]], "layout": "split"}, {"title": "（二）自我克制：更多的快樂、創意與尊嚴 王溢嘉", "page": "", "blocks": [["text", "para", "孔子是個很注重自我克制、自我約束的人，他說：「以約，失之者鮮矣。」（里仁）意思是能自我約束的人，犯的過錯就很少。但所謂克制或約束絕無禁止之意，而是要「約之以禮」（雍也）、「克己復禮」（顏淵），讓欲望和行為回復到（或符合）「禮」的儀軌上。當然，「非禮勿視，非禮勿聽，非禮勿言，非禮勿動」（顏淵）的幾個「勿」可能給人很大的束縛、壓迫感，但這其實是受到傳統解釋窠臼「束縛」的關係。"], ["text", "para", "當我們說「克制」時，針對的是不當、有害的欲望，但什麼是「不當」、「有害」？習慣的想法是指「過多」的欲望，其實，有些欲望「過少」（譬如厭食）也是有害的，這時就要克制自己想要成為「纖瘦美女」的想望，而「增加」自己的食欲。所以，我們要克制的其實是「過度」──過多或過少的欲望都屬不當。"], ["text", "q", "【(A)】1.文中首段畫線處說明孔子的為人，下列詞語何者符合對孔子的形容？"], ["text", "para", "(甲)束身自修　　(乙)頤指進退　　(丙)嚴以律己　　(丁)深文周納"], ["text", "opt", "(A)(甲)(丙)　　　　　(B)(乙)(丁)"], ["text", "opt", "(C)(甲)(乙)(丙)　　　　(D)(乙)(丙)(丁)"], ["text", "exp", "【解析】(A)由「注重自我克制、自我約束」可知(甲)、(丙)符合孔子之為人。(甲)約束自己、自我修養。(乙)用面部表情指揮人進退。比喻以高傲的態度指揮別人。(丙)以嚴格的態度來約束自己。(丁)指不根據事實，而巧妙的援引苛刻的法條，陷人入罪。"], ["text", "q", "【(A)】2.關於「以約，失之者鮮矣」的說明，下列何者理解不適當？"], ["text", "opt", "(A)「約」是約束、管束、克制、限制，具有完全禁止的意思"], ["text", "opt", "(B)依照「禮」來約束身心，讓欲望和行為符合「禮」的規範"], ["text", "opt", "(C)「非禮勿視」之「勿」給人束縛感，與傳統解釋窠臼有關"], ["text", "opt", "(D)一個能夠懂得約束自己的人，比較少會有犯下過錯的時候"], ["text", "exp", "【解析】(A)由「但所謂克制或約束絕無禁止之意」，可知並不是完全禁止的意思。(B)由「要『約之以禮』、『克己復禮』，讓欲望和行為回復到（或符合）『禮』的儀軌上」可知。(C)由「『非禮勿視，非禮勿聽，非禮勿言，非禮勿動』的幾個『勿』可能給人很大的束縛、壓迫感，但這其實是受到傳統解釋窠臼『束縛』的關係」可知。(D)由「能自我約束的人，犯的過錯就很少」可知。"], ["text", "q", "【(D)】3.下列何者最符合上文所述？"], ["text", "opt", "(A)「克制」，是針對人們內心產生的所有欲望而言"], ["text", "opt", "(B)「過多」的欲望有益人類的進步發展，無須克制"], ["text", "opt", "(C)「厭食」、「纖瘦美女」是正確的想望及行為表現"], ["text", "opt", "(D)「過度」指超越適當的限度，易損害自己的身體"], ["text", "exp", "【解析】(A)由「當我們說『克制』時，針對的是不當、有害的欲望」，可知不是針對人心裡產生的所有的欲望而言。(B)由「但什麼是『不當』、『有害』？習慣的想法是指『過多』的欲望」，可知作者認為「過多」的欲望，包含「不當」、「有害」的，需懂得克制。(C)由「有些欲望『過少』（譬如厭食）也是有害的、這時就要克制自己想要」，可知是有害自己的想望及行為表現。(D)由「我們要克制的其實是『過度』──過多或過少的欲望都屬不當」可知。"], ["text", "para", "【賞析】本文作者認為孔子是一位自我克制、嚴以律己的人，從論語中提及的「以約，失之者鮮矣」、「約之以禮」、「克己復禮」到「非禮勿視，非禮勿聽，非禮勿言，非禮勿動」，作者逐一剖析「克制」的深層意涵。「克制」絕無禁止的意思，「克制」乃是針對不當、有害的欲望而言，我們要克制的是「過度」，而過多或過少的欲望皆屬不當的行為。"]], "layout": "split"}, {"title": "伍 統測試題精選", "page": "", "blocks": [["text", "mj", "伍　統測試題精選"], ["text", "q", "【(A)】1.王同學將(甲)～(己)六部典籍，填入按「作者」、「經書子書」、「史書」分類的交叉查詢表，其中位置正確的典籍為何？ 【109統測】"], ["table", "", [["", "作者"]]], ["table", "", [["", "集體作者", "單一具名作者"]]], ["table", "", [["經書子書", "語錄體", "(甲)論語", "(乙)荀子"], ["", "專題論述", "(丙)孟子", ""], ["史書", "編年體", "(丁)戰國策", ""], ["", "紀傳體", "(戊)左傳", "(己)史記"]]], ["table", "", [["註：「語錄體」是將對話紀錄直接呈現，「專題論述」為一篇論一主題，通常主題即是篇名。"]]], ["text", "opt", "(A)(甲)(己)"], ["text", "opt", "(B)(乙)(丙)(戊)"], ["text", "opt", "(C)(甲)(丙)(丁)(己)"], ["text", "opt", "(D)(乙)(丁)(戊)(己)"], ["text", "exp", "【解析】(乙)荀子為專題論述；(丙)孟子為語錄體；(丁)戰國策為國別史體例；(戊)左傳為編年體著作。因此答案選(A)。"], ["text", "q", "【(A)】2.下列選項，何者說明下文「在儒家價值體系中早有明確的分劃」？ <span class=\"jy-cir\">①</span><span class=\"jy-blank\" onclick=\"this.classList.toggle(&#39;show&#39;)\"><span class=\"jy-blank-ph\">&nbsp;&nbsp;&nbsp;&nbsp;</span><span class=\"jy-blank-ans\">108　統測</span></span>"], ["text", "para", "知識份子的立身處世之道，在儒家價值體系中早有明確的分劃，那就是兼善或獨善—將自己置身於政治漩渦之中，一伸治平之志；或蟬蛻於塵囂之中，自致於寰區之外，和政治保持某種程度的疏離。 （改寫自逯耀東　且做神州袖手人）"], ["text", "opt", "(A)用之則行，舍之則藏"], ["text", "opt", "(B)君子喻於義，小人喻於利"], ["text", "opt", "(C)見賢思齊焉，見不賢而內自省也"], ["text", "opt", "(D)政者，正也。子帥以正，孰敢不正"], ["text", "exp", "【解析】題幹敘述強調「在儒家價值體系中早有明確的分劃」是「兼善或獨善」，則相應的答案為(A)。"], ["text", "trans", "【語譯】(A)受到任用，就出來將治國平天下的大道推行於世；不被任用時，則沉潛努力充實自我，等待良機。論語　述而。(B)君子重視的是道義，而小人只知道利益。論語　里仁。(C)看見賢德之人就向他看齊，期許自己能像對方一樣好；看見不賢德之人，別急著批評指責，內心應先反省，衡量自己是否有像對方一樣的過錯？論語　里仁。(D)政治，就是端正之道。自己以身表率，用正直不偏私的方式來領導眾人，那麼誰還敢不行正道呢？論語　顏淵。"], ["text", "q", "【(A)】3.下列甲、乙兩朵文字雲由兩本經典製成，書中使用次數越多的字，字體越大，則這兩本經典依序應是： <span class=\"jy-cir\">②</span><span class=\"jy-blank\" onclick=\"this.classList.toggle(&#39;show&#39;)\"><span class=\"jy-blank-ph\">&nbsp;&nbsp;&nbsp;&nbsp;</span><span class=\"jy-blank-ans\">107　統測</span></span>"], ["text", "para", "<img src='img/侍坐/1dd77cf26ae06d42.png' style='max-width:100%;width:460px;display:block;margin:10px auto' alt=''>"], ["text", "opt", "(A)論語／左傳"], ["text", "opt", "(B)論語／荀子"], ["text", "opt", "(C)孟子／左傳"], ["text", "opt", "(D)孟子／荀子"], ["text", "exp", "【解析】由甲圖出現「君子」、「小人」、「子路」、「孔子」等文字資料可知為論語；由乙圖出現「晉」、「公子」、「盟」、「鄭」、「寡君」、「使」、「師」等文字資料可推知為左傳。左傳記述春秋時發生的戰爭事件，如「晉　楚　城濮之戰」、「秦　晉　殽之戰」等。"]], "layout": "split"}], "charBian": [{"name": "以", "pages": [{"sub": "字義辨析", "body": "<table class=\"jy-table\">\n<tr><th class=\"jy-th-full\" colspan=\"2\">義 ｜ 例</th></tr>\n<tr><th class=\"jy-th\">因為</th><td><b>以</b>吾一日長乎爾<br>毋吾<b>以</b>也</td></tr>\n<tr><th class=\"jy-th\">用</th><td>為國<b>以</b>禮<br>加之<b>以</b>師旅，因之<b>以</b>饑饉</td></tr>\n</table>"}]}, {"name": "如", "pages": [{"sub": "字義辨析", "body": "<table class=\"jy-table\">\n<tr><th class=\"jy-th-full\" colspan=\"2\">義 ｜ 例</th></tr>\n<tr><th class=\"jy-th\">如果</th><td><b>如</b>或知爾，則何以哉</td></tr>\n<tr><th class=\"jy-th\">或者</th><td>方六、七十，<b>如</b>五、六十</td></tr>\n<tr><th class=\"jy-th\">至於</th><td><b>如</b>其禮樂，以俟君子</td></tr>\n</table>"}]}, {"name": "與", "pages": [{"sub": "義辨", "body": "<table class=\"jy-table\">\n<tr><th class=\"jy-th-full\" colspan=\"3\">音 ｜ 義 ｜ 例</th></tr>\n<tr><th class=\"jy-th\">ㄩˇ</th><td>贊同、讚許</td><td>吾<b>與</b>點也</td></tr>\n<tr><th class=\"jy-th\">ㄩˇ</th><td>支持、贊助</td><td>天道無親，常<b>與</b>善人（《老子》第七十九章）</td></tr>\n<tr><th class=\"jy-th\">ㄩˇ</th><td>親附</td><td>失其所<b>與</b>，不知（《左傳．燭之武退秦師》）</td></tr>\n<tr><th class=\"jy-th\">ㄩˇ</th><td>向、對</td><td><b>與</b>虎謀皮</td></tr>\n<tr><th class=\"jy-th\">ㄩˇ</th><td>通「舉」，推舉、選拔</td><td>選賢<b>與</b>能（《禮記．大同與小康》）</td></tr>\n<tr><th class=\"jy-th\">ㄩˇ</th><td>等待</td><td>時不我<b>與</b></td></tr>\n<tr><th class=\"jy-th\">ㄩˇ</th><td>同類</td><td>民胞物<b>與</b></td></tr>\n<tr><th class=\"jy-th\">ㄩˊ</th><td>通「歟」，句末助詞，表達疑問、反詰、感嘆的語氣</td><td>唯赤則非邦也<b>與</b></td></tr>\n<tr><th class=\"jy-th\">ㄩˋ</th><td>參加</td><td>參<b>與</b></td></tr>\n</table>"}]}, {"name": "舍", "pages": [{"sub": "形音義辨析", "body": "<table class=\"jy-table\">\n<tr><th class=\"jy-th-full\" colspan=\"3\">音 ｜ 義 ｜ 例</th></tr>\n<tr><th class=\"jy-th\">ㄕㄜˇ</th><td>放下</td><td>鼓瑟希，鏗爾，<b>舍</b>瑟而作</td></tr>\n<tr><th class=\"jy-th\">ㄕㄜˇ</th><td>停止、休息</td><td>逝者如斯夫！不<b>舍</b>晝夜（《論語．子罕》）<br>駑馬十駕，功在不<b>舍</b>（《荀子．勸學》）</td></tr>\n<tr><th class=\"jy-th\">ㄕㄜˋ</th><td>房屋</td><td>土地平曠，屋<b>舍</b>儼然（陶淵明〈桃花源記〉）</td></tr>\n<tr><th class=\"jy-th\">ㄕㄜˋ</th><td>三十里</td><td>退避三<b>舍</b></td></tr>\n</table>"}]}]}]);
